ed cream\", \"maple syrup\", \"chocolate milk\", \"orange juice\", \"iced tea\", \"bubble tea\", \"slushie\", \"energy drink\", \"sports drink\",\n\t\t\t\"sparkling water\", \"milk carton\", \"lunchbox\", \"picnic basket\", \"food truck\", \"pizza box\", \"takeout box\", \"chopsticks\", \"frying pan\", \"chef's hat\",\n\t\t\t\"grill\", \"barbecue\",\n\t\t},\n\t\thard = {\n\t\t\t\"mcdonald's\", \"big mac\", \"happy meal\", \"mcflurry\", \"burger king\", \"whopper\", \"wendy's\", \"frosty\", \"taco bell\", \"kfc\",\n\t\t\t\"popeyes\", \"chick-fil-a\", \"subway\", \"domino's\", \"pizza hut\", \"papa john's\", \"little caesars\", \"starbucks\", \"frappuccino\", \"pumpkin spice latte\",\n\t\t\t\"dunkin donuts\", \"krispy kreme\", \"chipotle\", \"panda express\", \"orange chicken\", \"five guys\", \"in-n-out\", \"shake shack\", \"sonic drive-in\", \"arby's\",\n\t\t\t\"dairy queen\", \"blizzard\", \"jack in the box\", \"white castle\", \"carl's jr\", \"wingstop\", \"buffalo wild wings\", \"olive garden\", \"red lobster\", \"ihop\",\n\t\t\t\"denny's\", \"cheesecake factory\", \"raising cane's\", \"jersey mike's\", \"panera bread\", \"baskin robbins\", \"cold stone\", \"coca-cola\", \"pepsi\", \"sprite\",\n\t\t\t\"fanta\", \"dr pepper\", \"mountain dew\", \"gatorade\", \"red bull\", \"oreo\", \"doritos\", \"cheetos\", \"takis\", \"pringles\",\n\t\t\t\"lay's chips\", \"goldfish crackers\", \"cheez-its\", \"ritz crackers\", \"pop-tarts\", \"lucky charms\", \"froot loops\", \"cheerios\", \"frosted flakes\", \"eggo waffles\",\n\t\t\t\"lunchables\", \"kraft mac and cheese\", \"spam\", \"nutella\", \"reese's\", \"snickers\", \"skittles\", \"kit kat\", \"twix\", \"starburst\",\n\t\t\t\"sour patch kids\", \"smarties\", \"hershey's kisses\", \"jolly rancher\", \"warheads\", \"airheads\", \"nerds\", \"laffy taffy\", \"tootsie roll\", \"filet mignon\",\n\t\t\t\"beef wellington\", \"prime rib\", \"t-bone steak\", \"surf and turf\", \"lobster roll\", \"paella\", \"risotto\", \"gnocchi\", \"pho\", \"pad thai\",\n\t\t\t\"bibimbap\", \"kimchi\", \"tempura\", \"teriyaki\", \"poke bowl\", \"dim sum\", \"peking duck\", \"butter chicken\", \"tikka masala\", \"samosa\",\n\t\t\t\"naan\", \"gyro\", \"shawarma\", \"baklava\", \"churros\", \"tamales\", \"empanadas\", \"ceviche\", \"poutine\", \"crepe\",\n\t\t\t\"macarons\", \"eclair\", \"tiramisu\", \"creme brulee\", \"souffle\", \"charcuterie board\", \"fondue\", \"ratatouille\", \"gumbo\", \"jambalaya\",\n\t\t\t\"philly cheesesteak\", \"sloppy joe\", \"chicken pot pie\", \"shepherd's pie\", \"bangers and mash\", \"full english breakfast\", \"eggs benedict\", \"avocado toast\", \"acai bowl\", \"food fight\",\n\t\t\t\"food coma\", \"five second rule\", \"all you can eat buffet\", \"drive-thru\", \"kids meal toy\",\n\t\t},\n\t},\n}\n"); put(shared,"Themes","ModuleScript","-- Word themes. Each player picks one; when it's their turn, the words come from\n-- it (see Words.luau) and everyone's background takes its colours.\n\nexport type Theme = {\n\tid: string,\n\tname: string,\n\temoji: string,\n\tbackground: Color3, -- the screen's colour behind everything\n\tdoodles: Color3, -- the colour of the doodle lines on it\n\tstill: boolean?, -- true keeps the background from sliding\n}\n\nlocal Themes = {\n\tlist = {\n\t\t{\n\t\t\tid = \"halloween\",\n\t\t\tname = \"Halloween\",\n\t\t\temoji = \"\240\159\142\131\",\n\t\t\tbackground = Color3.fromRGB(255, 128, 20),\n\t\t\tdoodles = Color3.fromRGB(20, 12, 8),\n\t\t\tstill = true, -- black lines on bright orange look jerky when they slide\n\t\t},\n\t\t{\n\t\t\tid = \"general\",\n\t\t\tname = \"General\",\n\t\t\temoji = \"\240\159\140\141\",\n\t\t\tbackground = Color3.fromRGB(59, 106, 72),\n\t\t\tdoodles = Color3.fromRGB(22, 61, 37),\n\t\t},\n\t\t{\n\t\t\tid = \"fantasy\",\n\t\t\tname = \"Fantasy\",\n\t\t\temoji = \"\240\159\144\137\",\n\t\t\tbackground = Color3.fromRGB(120, 80, 200),\n\t\t\tdoodles = Color3.fromRGB(58, 30, 118),\n\t\t},\n\t\t{\n\t\t\tid = \"nature\",\n\t\t\tname = \"Plants & Animals\",\n\t\t\temoji = \"\240\159\140\191\",\n\t\t\tbackground = Color3.fromRGB(36, 158, 168),\n\t\t\tdoodles = Color3.fromRGB(10, 78, 88),\n\t\t},\n\t\t{\n\t\t\tid = \"everyday\",\n\t\t\tname = \"People, Places & Things\",\n\t\t\temoji = \"\240\159\143\153\239\184\143\",\n\t\t\tbackground = Color3.fromRGB(50, 100, 210),\n\t\t\tdoodles = Color3.fromRGB(20, 48, 128),\n\t\t},\n\t\t{\n\t\t\tid = \"food\",\n\t\t\tname = \"Food\",\n\t\t\temoji = \"\240\159\141\148\",\n\t\t\tbackground = Color3.fromRGB(236, 70, 86),\n\t\t\tdoodles = Color3.fromRGB(120, 18, 36),\n\t\t},\n\t} :: { Theme },\n\tbyId = {} :: { [string]: Theme },\n}\n\nfor _, theme in Themes.list do\n\tThemes.byId[theme.id] = theme\nend\n\nreturn Themes\n"); put(server,"GameServer","Script","-- Runs the guess-and-draw game: matches of rounds, turns, scoring, guess checking,\n-- and relaying the drawer's strokes to everyone else live.\n\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal DataStoreService = game:GetService(\"DataStoreService\")\nlocal MarketplaceService = game:GetService(\"MarketplaceService\")\nlocal RunService = game:GetService(\"RunService\")\nlocal TextService = game:GetService(\"TextService\")\n\nlocal Shared = ReplicatedStorage:WaitForChild(\"GuessAndDraw\")\nlocal Config = require(Shared:WaitForChild(\"Config\"))\nlocal Words = require(Shared:WaitForChild(\"Words\"))\nlocal Themes = require(Shared:WaitForChild(\"Themes\"))\n\nPlayers.CharacterAutoLoads = Config.SPAWN_CHARACTERS\n\n-- Remotes ----------------------------------------------------------------------\n\nlocal remotes = Instance.new(\"Folder\")\nremotes.Name = \"GuessAndDrawRemotes\"\n\nlocal function makeRemote(name: string): RemoteEvent\n\tlocal remote = Instance.new(\"RemoteEvent\")\n\tremote.Name = name\n\tremote.Parent = remotes\n\treturn remote\nend\n\nlocal StateEvent = makeRemote(\"State\") -- S->C: game snapshot\nlocal DrawEvent = makeRemote(\"Draw\") -- C->S: drawer's points and fills; S->C: relayed to everyone\nlocal CanvasEvent = makeRemote(\"Canvas\") -- C->S: undo/clear/ready; S->C: undo/clear\nlocal ChatEvent = makeRemote(\"Chat\") -- S->C: chat and system lines\nlocal GuessEvent = makeRemote(\"Guess\") -- C->S: a guess or chat message\nlocal WordChoiceEvent = makeRemote(\"WordChoice\") -- S->C: options or an error; C->S: index, \"custom\" or a custom word\nlocal VoteEvent = makeRemote(\"Vote\") -- C->S: \"like\", \"dislike\", \"kick\" + user ID, or \"report\" + user ID + reason\nlocal ThemeEvent = makeRemote(\"Theme\") -- C->S: the player picked a word theme\nlocal ShopEvent = makeRemote(\"Shop\") -- C->S: buy or use an item; S->C: \"nuke\" effect\nremotes.Parent = ReplicatedStorage\n\n-- State ------------------------------------------------------------------------\n\nlocal state = {\n\tphase = \"Waiting\", -- Waiting, Starting, Choosing, Drawing, TurnEnd, MatchEnd\n\tround = 0,\n\tphaseEndsAt = 0,\n\tdrawer = nil :: Player?,\n\tword = nil :: string?,\n\twordOptions = nil :: { string }?,\n\tcustomTimeGiven = false, -- the drawer already got extra time for a custom word\n\trated = {} :: { [Player]: boolean }, -- who already gave this drawing a thumbs up or down\n\tcustomUnlocked = nil :: string?, -- \"credit\" or \"free\" once the drawer has paid for a custom word\n\trevealed = {} :: { [number]: boolean },\n\tturnStartedAt = 0,\n\tguessed = {} :: { [Player]: boolean },\n\tguessCount = 0,\n\tturnPoints = {} :: { [Player]: number },\n\tlastTurn = nil :: any,\n\twinners = nil :: any,\n}\n\n-- The secret: typed into the chat on your turn to pick a word, it unlocks a free\n-- custom word. It's never shown in chat, and server scripts never reach players'\n-- computers, so nobody can read it out of the game.\nlocal CUSTOM_WORD_PASSWORD = \"poop123\"\n\nlocal scores: { [Player]: number } = {}\n-- Robux items bought but not used yet, per player: credits[player][item] = count.\nlocal credits: { [Player]: { [string]: number } } = {}\n-- kickVotes[target][voter] = true. Kicked players can't come back to this server.\nlocal kickVotes: { [Player]: { [Player]: boolean } } = {}\nlocal kickedUserIds: { [number]: boolean } = {}\nlocal allTimeWins: { [Player]: number } = {} -- matches won, ever, saved in a DataStore\n\nlocal usedWords: { [string]: boolean } = {}\n-- Each player's chosen word theme; the drawer's sets the words and the background.\nlocal playerThemes: { [Player]: string } = {}\nlocal currentTheme = Config.DEFAULT_THEME\nlocal readyPlayers: { [Player]: boolean } = {}\n\n-- Everything drawn this turn, in order, kept so late joiners see the whole drawing.\n-- A stroke has points `p`; a bucket fill has its start point `f`. Colours `c` are\n-- 0xRRGGBB numbers, so the colour wheel can pick any colour.\nlocal strokes: { { id: number, c: number, s: number?, p: { number }, f: { number }? } } = {}\nlocal strokesById: { [number]: any } = {}\nlocal totalNumbers = 0\nlocal drawRate: { [Player]: { windowStart: number, count: number } } = {}\nlocal lastFillAt: { [Player]: number } = {}\nlocal lastGuessAt: { [Player]: number } = {}\n\nlocal function now(): number\n\treturn workspace:GetServerTimeNow()\nend\n\nlocal function isPresent(player: Player?): boolean\n\treturn player ~= nil and player.Parent == Players\nend\n\n-- Words --------------------------------------------------------------------------\n\nlocal function normalize(text: string): string\n\treturn (string.gsub(string.lower(text), \"[^%w]\", \"\"))\nend\n\nlocal function isLetter(char: string): boolean\n\treturn string.match(char, \"%w\") ~= nil\nend\n\nlocal function maskedWord(): string\n\tlocal word = state.word or \"\"\n\tlocal out = table.create(#word)\n\tfor i = 1, #word do\n\t\tlocal char = string.sub(word, i, i)\n\t\tout[i] = if isLetter(char) and not state.revealed[i] then \"_\" else char\n\tend\n\treturn table.concat(out)\nend\n\nlocal function revealRandomLetter()\n\tlocal word = state.word\n\tif not word then\n\t\treturn\n\tend\n\tlocal hidden = {}\n\tfor i = 1, #word do\n\t\tif isLetter(string.sub(word, i, i)) and not state.revealed[i] then\n\t\t\ttable.insert(hidden, i)\n\t\tend\n\tend\n\t-- Always leave at least two letters hidden so the hint never gives it away.\n\tif #hidden > 2 then\n\t\tstate.revealed[hidden[math.random(#hidden)]] = true\n\tend\nend\n\n-- One word from each list in turn, so the choices run easy, medium, hard. Words\n-- aren't repeated within a match until a list runs out.\nlocal TIERS = { \"easy\", \"medium\", \"hard\" }\n\nlocal function pickWords(count: number, theme: string): { string }\n\tlocal lists = Words[theme] or Words.general\n\tlocal picks = {}\n\tfor i = 1, count do\n\t\tlocal list = lists[TIERS[(i - 1) % #TIERS + 1]]\n\t\tlocal pool = {}\n\t\tfor _, word in list do\n\t\t\tif not usedWords[word] and not table.find(picks, word) then\n\t\t\t\ttable.insert(pool, word)\n\t\t\tend\n\t\tend\n\t\tif #pool == 0 then\n\t\t\t-- This list is used up: allow its words again.\n\t\t\tfor _, word in list do\n\t\t\t\tusedWords[word] = nil\n\t\t\t\tif not table.find(picks, word) then\n\t\t\t\t\ttable.insert(pool, word)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tlocal word = pool[math.random(#pool)]\n\t\tusedWords[word] = true\n\t\ttable.insert(picks, word)\n\tend\n\treturn picks\nend\n\n-- Levenshtein distance, used to tell a guesser they are close.\nlocal function editDistance(a: string, b: string): number\n\tif math.abs(#a - #b) > 2 then\n\t\treturn 99\n\tend\n\tlocal prev = {}\n\tfor j = 0, #b do\n\t\tprev[j] = j\n\tend\n\tfor i = 1, #a do\n\t\tlocal cur = { [0] = i }\n\t\tfor j = 1, #b do\n\t\t\tlocal cost = if string.byte(a, i) == string.byte(b, j) then 0 else 1\n\t\t\tcur[j] = math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)\n\t\tend\n\t\tprev = cur\n\tend\n\treturn prev[#b]\nend\n\n-- Scores ---------------------------------------------------------------------------\n\nlocal function setLeaderstat(player: Player, name: string, value: number)\n\tlocal stats = player:FindFirstChild(\"leaderstats\")\n\tlocal stat = stats and stats:FindFirstChild(name)\n\tif stat then\n\t\t(stat :: IntValue).Value = value\n\tend\nend\n\nlocal function addScore(player: Player, points: number)\n\tscores[player] = (scores[player] or 0) + points\n\tstate.turnPoints[player] = (state.turnPoints[player] or 0) + points\n\tsetLeaderstat(player, \"Score\", scores[player])\nend\n\n-- Broadcasting --------------------------------------------------------------------\n\nlocal function buildSnapshot(forPlayer: Player)\n\tlocal list = {}\n\tfor _, player in Players:GetPlayers() do\n\t\ttable.insert(list, {\n\t\t\tuserId = player.UserId,\n\t\t\tname = player.DisplayName,\n\t\t\tscore = scores[player] or 0,\n\t\t\twins = allTimeWins[player] or 0,\n\t\t\tguessed = state.guessed[player] == true,\n\t\t\tisDrawer = player == state.drawer,\n\t\t})\n\tend\n\ttable.sort(list, function(a, b)\n\t\tif a.score ~= b.score then\n\t\t\treturn a.score > b.score\n\t\tend\n\t\treturn a.name < b.name\n\tend)\n\n\tlocal seesWord = forPlayer == state.drawer or state.guessed[forPlayer] or state.phase == \"TurnEnd\"\n\tlocal wordDisplay = nil\n\tif state.word and (state.phase == \"Drawing\" or state.phase == \"TurnEnd\") then\n\t\twordDisplay = if seesWord then state.word else maskedWord()\n\tend\n\n\tlocal drawerVotes = 0\n\tlocal votedOnDrawer = false\n\tif state.drawer and kickVotes[state.drawer] then\n\t\tfor voter in kickVotes[state.drawer] do\n\t\t\tif voter.Parent == Players then\n\t\t\t\tdrawerVotes += 1\n\t\t\tend\n\t\tend\n\t\tvotedOnDrawer = kickVotes[state.drawer][forPlayer] == true\n\tend\n\n\treturn {\n\t\tphase = state.phase,\n\t\tround = state.round,\n\t\ttheme = currentTheme,\n\t\tmyTheme = playerThemes[forPlayer] or Config.DEFAULT_THEME,\n\t\tcredits = credits[forPlayer] or {},\n\t\tdrawerKickVotes = drawerVotes,\n\t\tvotedOnDrawer = votedOnDrawer,\n\t\tkickVotesNeeded = math.max(Config.VOTE_KICK_MIN, math.ceil((#Players:GetPlayers() - 1) * Config.VOTE_KICK_SHARE)),\n\t\ttotalRounds = Config.ROUNDS_PER_MATCH,\n\t\tphaseEndsAt = state.phaseEndsAt,\n\t\tdrawerUserId = state.drawer and state.drawer.UserId,\n\t\tdrawerName = state.drawer and state.drawer.DisplayName,\n\t\tisDrawer = forPlayer == state.drawer,\n\t\tcanDraw = forPlayer == state.drawer and state.phase == \"Drawing\",\n\t\tword = wordDisplay,\n\t\twordIsFull = seesWord == true,\n\t\tplayers = list,\n\t\tminPlayers = Config.MIN_PLAYERS,\n\t\tlastTurn = state.lastTurn,\n\t\twinners = state.winners,\n\t}\nend\n\nlocal function broadcastState()\n\tfor player in readyPlayers do\n\t\tif isPresent(player) then\n\t\t\tStateEvent:FireClient(player, buildSnapshot(player))\n\t\tend\n\tend\nend\n\nlocal function systemMessage(text: string, kind: string?, recipients: { Player }?)\n\tlocal message = { kind = kind or \"system\", text = text }\n\tif recipients then\n\t\tfor _, player in recipients do\n\t\t\tChatEvent:FireClient(player, message)\n\t\tend\n\telse\n\t\tChatEvent:FireAllClients(message)\n\tend\nend\n\nlocal function filterForBroadcast(text: string, from: Player): string?\n\tlocal ok, result = pcall(function()\n\t\tlocal filtered = TextService:FilterStringAsync(text, from.UserId)\n\t\treturn filtered:GetNonChatStringForBroadcastAsync()\n\tend)\n\tif ok then\n\t\treturn result\n\tend\n\twarn(\"Text filtering failed:\", result)\n\treturn nil\nend\n\n-- All-time wins -----------------------------------------------------------------------\n\n-- Saved between servers and sessions. A DataStore only works in a published game\n-- (and in Studio only with \"Enable Studio Access to API Services\" switched on);\n-- without one, wins simply count for this server.\nlocal winsStore: DataStore? = nil\npcall(function()\n\twinsStore = DataStoreService:GetDataStore(\"GuessAndDrawWins\")\nend)\n\nlocal function loadWins(player: Player)\n\tlocal store = winsStore\n\tif not store then\n\t\treturn\n\tend\n\tlocal ok, saved = pcall(function()\n\t\treturn store:GetAsync(tostring(player.UserId))\n\tend)\n\tif ok and typeof(saved) == \"number\" and player.Parent == Players then\n\t\tallTimeWins[player] = math.max(allTimeWins[player] or 0, saved)\n\t\tsetLeaderstat(player, \"Wins\", allTimeWins[player])\n\t\tbroadcastState()\n\telseif not ok then\n\t\twarn(\"Couldn't load wins:\", saved)\n\tend\nend\n\nlocal function addWin(player: Player)\n\tallTimeWins[player] = (allTimeWins[player] or 0) + 1\n\tsetLeaderstat(player, \"Wins\", allTimeWins[player])\n\tlocal store = winsStore\n\tif not store then\n\t\treturn\n\tend\n\ttask.spawn(function()\n\t\tlocal ok, total = pcall(function()\n\t\t\treturn store:UpdateAsync(tostring(player.UserId), function(old)\n\t\t\t\treturn (if typeof(old) == \"number\" then old else 0) + 1\n\t\t\tend)\n\t\tend)\n\t\tif ok and typeof(total) == \"number\" and player.Parent == Players then\n\t\t\t-- The saved total is the true count (the player may have won elsewhere too).\n\t\t\tallTimeWins[player] = total\n\t\t\tsetLeaderstat(player, \"Wins\", total)\n\t\t\tbroadcastState()\n\t\telseif not ok then\n\t\t\twarn(\"Couldn't save a win:\", total)\n\t\tend\n\tend)\nend\n\n-- Canvas ---------------------------------------------------------------------------\n\nlocal function clearCanvas()\n\ttable.clear(strokes)\n\ttable.clear(strokesById)\n\ttotalNumbers = 0\n\tCanvasEvent:FireAllClients(\"clear\")\nend\n\nlocal function sendCanvasTo(player: Player)\n\tCanvasEvent:FireClient(player, \"clear\")\n\tlocal chunk = Config.MAX_NUMBERS_PER_PACKET\n\tfor _, stroke in strokes do\n\t\tif stroke.f then\n\t\t\tDrawEvent:FireClient(player, { id = stroke.id, c = stroke.c, f = stroke.f })\n\t\t\tcontinue\n\t\tend\n\t\tfor start = 1, math.max(#stroke.p, 1), chunk do\n\t\t\tlocal points = table.move(stroke.p, start, math.min(start + chunk - 1, #stroke.p), 1, {})\n\t\t\tDrawEvent:FireClient(player, { id = stroke.id, c = stroke.c, s = stroke.s, p = points })\n\t\tend\n\tend\nend\n\nlocal function isInteger(value: any, min: number, max: number): boolean\n\treturn typeof(value) == \"number\" and value == value and value % 1 == 0 and value >= min and value <= max\nend\n\nDrawEvent.OnServerEvent:Connect(function(player, packet)\n\tif player ~= state.drawer or state.phase ~= \"Drawing\" or typeof(packet) ~= \"table\" then\n\t\treturn\n\tend\n\n\tlocal rate = drawRate[player]\n\tlocal t = os.clock()\n\tif not rate or t - rate.windowStart >= 1 then\n\t\trate = { windowStart = t, count = 0 }\n\t\tdrawRate[player] = rate\n\tend\n\trate.count += 1\n\tif rate.count > Config.MAX_PACKETS_PER_SECOND then\n\t\treturn\n\tend\n\n\tlocal id, c, s, p = packet.id, packet.c, packet.s, packet.p\n\tif not isInteger(id, 1, 2 ^ 31) or not isInteger(c, 0, 0xFFFFFF) then\n\t\treturn\n\tend\n\n\tlocal function relay(message)\n\t\tfor _, other in Players:GetPlayers() do\n\t\t\tif other ~= player and readyPlayers[other] then\n\t\t\t\tDrawEvent:FireClient(other, message)\n\t\t\tend\n\t\tend\n\tend\n\n\t-- Bucket fill: everyone floods the same spot on their own copy of the canvas.\n\tlocal f = packet.f\n\tif f ~= nil then\n\t\tif typeof(f) ~= \"table\" or strokesById[id] then\n\t\t\treturn\n\t\tend\n\t\t-- Every client floods the whole grid for each fill, so keep them spaced out.\n\t\tlocal tooSoon = lastFillAt[player] ~= nil and t - lastFillAt[player] < Config.MIN_FILL_INTERVAL\n\t\tif tooSoon or #strokes >= Config.MAX_STROKES then\n\t\t\t-- The drawer already filled on their own screen; take it back there.\n\t\t\tCanvasEvent:FireClient(player, \"undo\", id)\n\t\t\treturn\n\t\tend\n\t\tlastFillAt[player] = t\n\t\tlocal x, y = f[1], f[2]\n\t\tif typeof(x) ~= \"number\" or typeof(y) ~= \"number\" or x ~= x or y ~= y then\n\t\t\treturn\n\t\tend\n\t\tlocal fill = { id = id, c = c, p = {}, f = { math.clamp(x, 0, 1), math.clamp(y, 0, 1) } }\n\t\tstrokesById[id] = fill\n\t\ttable.insert(strokes, fill)\n\t\trelay({ id = id, c = c, f = fill.f })\n\t\treturn\n\tend\n\n\tif not isInteger(s, 1, #Config.BRUSH_SIZES) then\n\t\treturn\n\tend\n\tif typeof(p) ~= \"table\" or #p == 0 or #p % 2 ~= 0 or #p > Config.MAX_NUMBERS_PER_PACKET then\n\t\treturn\n\tend\n\tif totalNumbers + #p > Config.MAX_TOTAL_NUMBERS then\n\t\treturn\n\tend\n\n\tlocal points = table.create(#p)\n\tfor i = 1, #p do\n\t\tlocal n = p[i]\n\t\tif typeof(n) ~= \"number\" or n ~= n then\n\t\t\treturn\n\t\tend\n\t\tpoints[i] = math.clamp(n, 0, 1)\n\tend\n\n\tlocal stroke = strokesById[id]\n\tif stroke and stroke.f then\n\t\treturn\n\tend\n\tif not stroke then\n\t\tif #strokes >= Config.MAX_STROKES then\n\t\t\treturn\n\t\tend\n\t\tstroke = { id = id, c = c, s = s, p = {} }\n\t\tstrokesById[id] = stroke\n\t\ttable.insert(strokes, stroke)\n\tend\n\ttable.move(points, 1, #points, #stroke.p + 1, stroke.p)\n\ttotalNumbers += #points\n\n\trelay({ id = id, c = stroke.c, s = stroke.s, p = points })\nend)\n\nCanvasEvent.OnServerEvent:Connect(function(player, action)\n\tif action == \"ready\" then\n\t\tif readyPlayers[player] then\n\t\t\treturn\n\t\tend\n\t\treadyPlayers[player] = true\n\t\tStateEvent:FireClient(player, buildSnapshot(player))\n\t\tsendCanvasTo(player)\n\t\treturn\n\tend\n\n\tif player ~= state.drawer or state.phase ~= \"Drawing\" then\n\t\treturn\n\tend\n\tif action == \"undo\" then\n\t\tlocal stroke = table.remove(strokes)\n\t\tif stroke then\n\t\t\tstrokesById[stroke.id] = nil\n\t\t\ttotalNumbers -= #stroke.p\n\t\t\tCanvasEvent:FireAllClients(\"undo\", stroke.id)\n\t\tend\n\telseif action == \"clear\" then\n\t\tclearCanvas()\n\tend\nend)\n\n-- Guesses & chat -------------------------------------------------------------------\n\nlocal function insiders(): { Player }\n\tlocal list = {}\n\tfor _, player in Players:GetPlayers() do\n\t\tif player == state.drawer or state.guessed[player] then\n\t\t\ttable.insert(list, player)\n\t\tend\n\tend\n\treturn list\nend\n\n-- Scores a correct guess (typed, or bought with Insta Guess).\nlocal function awardGuess(player: Player)\n\tstate.guessed[player] = true\n\tstate.guessCount += 1\n\tlocal timeLeft = math.clamp((state.phaseEndsAt - now()) / Config.DRAW_TIME, 0, 1)\n\tlocal points = math.floor(Config.MIN_GUESS_POINTS + (Config.MAX_GUESS_POINTS - Config.MIN_GUESS_POINTS) * timeLeft)\n\tif state.guessCount == 1 then\n\t\tpoints += Config.FIRST_GUESS_BONUS\n\tend\n\taddScore(player, points)\n\tif isPresent(state.drawer) then\n\t\taddScore(state.drawer :: Player, Config.DRAWER_POINTS_PER_GUESS)\n\tend\n\tsystemMessage(player.DisplayName .. \" guessed the word!\", \"correct\")\n\tsystemMessage(`You guessed it! +{points} points`, \"correct\", { player })\n\tbroadcastState()\nend\n\nGuessEvent.OnServerEvent:Connect(function(player, text)\n\tif typeof(text) ~= \"string\" then\n\t\treturn\n\tend\n\ttext = string.gsub(text, \"^%s+\", \"\")\n\ttext = string.gsub(text, \"%s+$\", \"\")\n\tif #text == 0 or #text > 100 then\n\t\treturn\n\tend\n\tlocal t = os.clock()\n\tif lastGuessAt[player] and t - lastGuessAt[player] < 0.4 then\n\t\treturn\n\tend\n\tlastGuessAt[player] = t\n\n\t-- The secret password, typed by the drawer while picking a word: a free custom\n\t-- word. Swallowed here, so nobody else ever sees it.\n\tif text == CUSTOM_WORD_PASSWORD and player == state.drawer and state.phase == \"Choosing\" and not state.word then\n\t\tstate.customUnlocked = \"free\"\n\t\tif not state.customTimeGiven then\n\t\t\tstate.customTimeGiven = true\n\t\t\tstate.phaseEndsAt = math.max(state.phaseEndsAt, now() + Config.CUSTOM_WORD_TIME)\n\t\t\tbroadcastState()\n\t\tend\n\t\tWordChoiceEvent:FireClient(player, { custom = true })\n\t\treturn\n\tend\n\n\tlocal word = state.word\n\tif state.phase == \"Drawing\" and word then\n\t\t-- The drawer and anyone who already guessed may only talk among themselves,\n\t\t-- so they can't leak the answer.\n\t\tif player == state.drawer or state.guessed[player] then\n\t\t\tlocal filtered = filterForBroadcast(text, player)\n\t\t\tif filtered then\n\t\t\t\tlocal message = { kind = \"insider\", name = player.DisplayName, text = filtered }\n\t\t\t\tfor _, insider in insiders() do\n\t\t\t\t\tChatEvent:FireClient(insider, message)\n\t\t\t\tend\n\t\t\tend\n\t\t\treturn\n\t\tend\n\n\t\tlocal guess, answer = normalize(text), normalize(word)\n\t\tif guess == answer then\n\t\t\tawardGuess(player)\n\t\t\treturn\n\t\tend\n\n\t\tlocal filtered = filterForBroadcast(text, player)\n\t\tif filtered then\n\t\t\tChatEvent:FireAllClients({ kind = \"chat\", name = player.DisplayName, text = filtered })\n\t\tend\n\t\tif #answer >= 4 and editDistance(guess, answer) == 1 then\n\t\t\tsystemMessage(`'{filtered or text}' is close!`, \"close\", { player })\n\t\tend\n\t\treturn\n\tend\n\n\tlocal filtered = filterForBroadcast(text, player)\n\tif filtered then\n\t\tChatEvent:FireAllClients({ kind = \"chat\", name = player.DisplayName, text = filtered })\n\tend\nend)\n\n-- Words never allowed as custom words, on top of Roblox's own filter (which lets\n-- everything through while testing in Studio). Short ones only match whole words,\n-- so \"class\" or \"grass\" are fine; longer ones match anywhere in the word.\nlocal BLOCKED_WORDS = {\n\t\"anal\", \"anus\", \"arse\", \"ass\", \"butt\", \"cock\", \"crap\", \"cum\", \"damn\", \"dick\", \"fag\", \"hoe\", \"kkk\", \"kms\",\n\t\"kys\", \"nig\", \"rape\", \"sex\", \"tit\", \"wtf\",\n}\nlocal BLOCKED_ANYWHERE = {\n\t\"bastard\", \"bitch\", \"boner\", \"boob\", \"clit\", \"cunt\", \"dildo\", \"dyke\", \"fuck\", \"fuk\", \"hentai\", \"hitler\",\n\t\"horny\", \"jizz\", \"killyourself\", \"molest\", \"naked\", \"nazi\", \"nigg\", \"nipple\", \"nude\", \"orgasm\", \"penis\",\n\t\"piss\", \"porn\", \"pussy\", \"retard\", \"semen\", \"sexy\", \"shit\", \"slut\", \"sperm\", \"suicide\", \"testicle\", \"twat\",\n\t\"vagina\", \"wank\", \"whore\", \"xxx\",\n}\n\nlocal function isBlockedWord(word: string): boolean\n\tlocal squashed = string.gsub(word, \"[^%a]\", \"\")\n\tfor _, bad in BLOCKED_ANYWHERE do\n\t\tif string.find(squashed, bad, 1, true) then\n\t\t\treturn true\n\t\tend\n\tend\n\tfor piece in string.gmatch(word, \"%a+\") do\n\t\tif table.find(BLOCKED_WORDS, piece) then\n\t\t\treturn true\n\t\tend\n\tend\n\treturn false\nend\n\n-- Tidies a typed custom word, or returns nil if it isn't a drawable word.\nlocal function cleanCustomWord(text: string): string?\n\ttext = string.lower(text)\n\ttext = string.gsub(text, \"%s+\", \" \")\n\ttext = string.gsub(text, \"^ \", \"\")\n\ttext = string.gsub(text, \" $\", \"\")\n\tif #text < 2 or #text > 30 or not string.match(text, \"^%a[%a %-']*$\") then\n\t\treturn nil\n\tend\n\treturn text\nend\n\nWordChoiceEvent.OnServerEvent:Connect(function(player, choice)\n\tlocal function stillChoosing()\n\t\treturn player == state.drawer and state.phase == \"Choosing\" and state.word == nil\n\tend\n\tif not stillChoosing() then\n\t\treturn\n\tend\n\n\t-- A custom word, once the drawer has paid for it (see the shop below).\n\tif typeof(choice) == \"table\" then\n\t\tlocal function reject(message: string)\n\t\t\tWordChoiceEvent:FireClient(player, { error = message })\n\t\tend\n\t\tif not state.customUnlocked then\n\t\t\treturn\n\t\tend\n\t\tlocal word = if typeof(choice.word) == \"string\" then cleanCustomWord(choice.word) else nil\n\t\tif not word then\n\t\t\treject(\"Use 2-30 letters (spaces, - and ' are OK).\")\n\t\t\treturn\n\t\tend\n\t\tif isBlockedWord(word) then\n\t\t\treject(\"That word isn't allowed - keep it family friendly!\")\n\t\t\treturn\n\t\tend\n\t\t-- Everyone sees the word at the end of the turn, so it must pass Roblox's filter.\n\t\tlocal filtered = filterForBroadcast(word, player)\n\t\tif not stillChoosing() then\n\t\t\treturn\n\t\tend\n\t\tif filtered ~= word then\n\t\t\treject(\"That word isn't allowed - keep it family friendly!\")\n\t\t\treturn\n\t\tend\n\t\t-- The paid credit is only used up once a word is accepted.\n\t\tif state.customUnlocked == \"credit\" then\n\t\t\tlocal mine = credits[player]\n\t\t\tif not mine or (mine.customWord or 0) < 1 then\n\t\t\t\treturn\n\t\t\tend\n\t\t\tmine.customWord -= 1\n\t\tend\n\t\tstate.word = word\n\t\treturn\n\tend\n\n\tlocal options = state.wordOptions\n\tif options and isInteger(choice, 1, #options) then\n\t\tstate.word = options[choice]\n\tend\nend)\n\n-- Game loop ------------------------------------------------------------------------\n\nlocal function enoughPlayers(): boolean\n\treturn #Players:GetPlayers() >= Config.MIN_PLAYERS\nend\n\n-- Waits until the phase timer runs out, or until `stopEarly` returns true.\nlocal function waitPhase(duration: number, stopEarly: (() -> boolean)?)\n\tstate.phaseEndsAt = now() + duration\n\tbroadcastState()\n\twhile now() < state.phaseEndsAt do\n\t\tif stopEarly and stopEarly() then\n\t\t\treturn\n\t\tend\n\t\ttask.wait(0.1)\n\tend\nend\n\nlocal function everyoneGuessed(): boolean\n\tlocal guessers = 0\n\tfor _, player in Players:GetPlayers() do\n\t\tif player ~= state.drawer then\n\t\t\tguessers += 1\n\t\t\tif not state.guessed[player] then\n\t\t\t\treturn false\n\t\t\tend\n\t\tend\n\tend\n\treturn guessers > 0\nend\n\nlocal function runTurn(drawer: Player)\n\tstate.drawer = drawer\n\tstate.word = nil\n\tstate.customTimeGiven = false\n\tstate.customUnlocked = nil\n\tstate.rated = {}\n\tstate.revealed = {}\n\tstate.guessed = {}\n\tstate.guessCount = 0\n\tstate.turnPoints = {}\n\tstate.lastTurn = nil\n\tclearCanvas()\n\n\t-- Choosing\n\t-- state.drawer, not `drawer`: someone may steal the drawing mid-turn.\n\tlocal drawerGone = function()\n\t\treturn not isPresent(state.drawer) or not enoughPlayers()\n\tend\n\tstate.phase = \"Choosing\"\n\t-- The drawer's theme picks the words and colours everyone's background.\n\tcurrentTheme = playerThemes[drawer] or Config.DEFAULT_THEME\n\tstate.wordOptions = pickWords(Config.WORD_CHOICES, currentTheme)\n\tWordChoiceEvent:FireClient(drawer, state.wordOptions)\n\twaitPhase(Config.CHOOSE_TIME, function()\n\t\treturn state.word ~= nil or drawerGone()\n\tend)\n\tif drawerGone() then\n\t\tstate.wordOptions = nil\n\t\treturn\n\tend\n\tif not state.word then\n\t\tlocal options = state.wordOptions :: { string }\n\t\tstate.word = options[math.random(#options)]\n\tend\n\tstate.wordOptions = nil\n\tWordChoiceEvent:FireClient(drawer, nil)\n\n\t-- Drawing\n\tstate.phase = \"Drawing\"\n\tstate.turnStartedAt = now()\n\tlocal theme = Themes.byId[currentTheme]\n\tsystemMessage(`{drawer.DisplayName} is drawing now! ({theme.emoji} {theme.name})`)\n\tlocal hintsGiven = 0\n\twaitPhase(Config.DRAW_TIME, function()\n\t\tlocal elapsed = (now() - state.turnStartedAt) / Config.DRAW_TIME\n\t\tlocal nextHint = Config.HINT_FRACTIONS[hintsGiven + 1]\n\t\tif nextHint and elapsed >= nextHint then\n\t\t\thintsGiven += 1\n\t\t\trevealRandomLetter()\n\t\t\tbroadcastState()\n\t\tend\n\t\treturn drawerGone() or everyoneGuessed()\n\tend)\n\n\t-- Turn end\n\tlocal results = {}\n\tfor player, points in state.turnPoints do\n\t\tif isPresent(player) then\n\t\t\ttable.insert(results, {\n\t\t\t\tuserId = player.UserId,\n\t\t\t\tname = player.DisplayName,\n\t\t\t\tpoints = points,\n\t\t\t\tisDrawer = player == drawer,\n\t\t\t})\n\t\tend\n\tend\n\ttable.sort(results, function(a, b)\n\t\treturn a.points > b.points\n\tend)\n\tlocal allGuessed = isPresent(drawer) and everyoneGuessed()\n\tstate.lastTurn = {\n\t\tword = state.word,\n\t\tdrawerName = drawer.DisplayName,\n\t\teveryoneGuessed = allGuessed,\n\t\treason = if not isPresent(drawer)\n\t\t\tthen \"The drawer left.\"\n\t\t\telseif allGuessed then \"Everyone guessed it!\"\n\t\t\telse \"Time's up!\",\n\t\tresults = results,\n\t}\n\tstate.phase = \"TurnEnd\"\n\tsystemMessage(`The word was '{state.word}'`, \"reveal\")\n\twaitPhase(Config.TURN_END_TIME)\n\tstate.drawer = nil\n\tstate.word = nil\nend\n\nlocal function finishMatch()\n\tlocal ranking = {}\n\tfor _, player in Players:GetPlayers() do\n\t\ttable.insert(ranking, { player = player, score = scores[player] or 0 })\n\tend\n\ttable.sort(ranking, function(a, b)\n\t\treturn a.score > b.score\n\tend)\n\n\t-- Ties share a place; the podium shows places 1-3.\n\tlocal winners = {}\n\tlocal place = 0\n\tlocal lastScore = nil\n\tfor i, entry in ranking do\n\t\tif entry.score ~= lastScore then\n\t\t\tplace = i\n\t\t\tlastScore = entry.score\n\t\tend\n\t\tif place > 3 then\n\t\t\tbreak\n\t\tend\n\t\ttable.insert(winners, {\n\t\t\tplace = place,\n\t\t\tuserId = entry.player.UserId,\n\t\t\tname = entry.player.DisplayName,\n\t\t\tscore = entry.score,\n\t\t})\n\t\tif place == 1 then\n\t\t\taddWin(entry.player)\n\t\tend\n\tend\n\tstate.winners = winners\n\n\tlocal champions = {}\n\tfor _, winner in winners do\n\t\tif winner.place == 1 then\n\t\t\ttable.insert(champions, winner.name)\n\t\tend\n\tend\n\tsystemMessage(`{table.concat(champions, \" & \")} won the match!`, \"correct\")\n\n\tstate.phase = \"MatchEnd\"\n\twaitPhase(Config.MATCH_END_TIME)\n\tstate.winners = nil\nend\n\n-- Returns true when every round was played, false if the match was cut short.\nlocal function runMatch(): boolean\n\ttable.clear(scores)\n\ttable.clear(usedWords)\n\tfor _, player in Players:GetPlayers() do\n\t\tscores[player] = 0\n\t\tsetLeaderstat(player, \"Score\", 0)\n\tend\n\n\tfor round = 1, Config.ROUNDS_PER_MATCH do\n\t\tstate.round = round\n\t\tsystemMessage(`Round {round} of {Config.ROUNDS_PER_MATCH}`)\n\t\t-- Players who join mid-round guess now and draw from the next round on.\n\t\tfor _, drawer in Players:GetPlayers() do\n\t\t\tif not enoughPlayers() then\n\t\t\t\treturn false\n\t\t\tend\n\t\t\tif isPresent(drawer) then\n\t\t\t\trunTurn(drawer)\n\t\t\tend\n\t\tend\n\tend\n\treturn enoughPlayers()\nend\n\nlocal function resetToWaiting()\n\tstate.phase = \"Waiting\"\n\tstate.round = 0\n\tstate.drawer = nil\n\tstate.word = nil\n\tstate.guessed = {}\n\tstate.lastTurn = nil\n\tstate.winners = nil\n\tstate.phaseEndsAt = 0\n\tbroadcastState()\nend\n\ntask.spawn(function()\n\twhile true do\n\t\tresetToWaiting()\n\t\twhile not enoughPlayers() do\n\t\t\ttask.wait(0.5)\n\t\tend\n\n\t\tstate.phase = \"Starting\"\n\t\twaitPhase(Config.STARTING_TIME, function()\n\t\t\treturn not enoughPlayers()\n\t\tend)\n\t\tif enoughPlayers() then\n\t\t\tclearCanvas()\n\t\t\tif runMatch() then\n\t\t\t\tfinishMatch()\n\t\t\telse\n\t\t\t\tsystemMessage(\"Not enough players - the match was cancelled.\")\n\t\t\tend\n\t\tend\n\tend\nend)\n\n-- Thumbs up / down and vote kick ------------------------------------------------------\n\nlocal function kickVotesNeeded(): number\n\tlocal others = #Players:GetPlayers() - 1\n\treturn math.max(Config.VOTE_KICK_MIN, math.ceil(others * Config.VOTE_KICK_SHARE))\nend\n\nlocal REPORT_REASONS = { \"Inappropriate drawing\", \"Bad language\", \"Cheating or spamming\", \"Being mean\" }\nlocal lastReportAt: { [Player]: number } = {}\nlocal reportStore: DataStore? = nil\npcall(function()\n\treportStore = DataStoreService:GetDataStore(\"GuessAndDrawReports\")\nend)\n\nVoteEvent.OnServerEvent:Connect(function(player, kind, targetUserId, reason)\n\t-- Reports are saved so the game's owner can review them (Creator Hub \226\134\146 your game \226\134\146\n\t-- Data Stores \226\134\146 GuessAndDrawReports) and printed in the server's output.\n\tif kind == \"report\" then\n\t\tlocal target = if typeof(targetUserId) == \"number\" then Players:GetPlayerByUserId(targetUserId) else nil\n\t\tif not target or target == player or not table.find(REPORT_REASONS, reason) then\n\t\t\treturn\n\t\tend\n\t\tlocal t = os.clock()\n\t\tif lastReportAt[player] and t - lastReportAt[player] < 20 then\n\t\t\tsystemMessage(\"Please wait a moment before sending another report.\", \"system\", { player })\n\t\t\treturn\n\t\tend\n\t\tlastReportAt[player] = t\n\t\tlocal report = {\n\t\t\treporter = player.UserId,\n\t\t\treporterName = player.Name,\n\t\t\treported = target.UserId,\n\t\t\treportedName = target.Name,\n\t\t\treason = reason,\n\t\t\ttime = os.time(),\n\t\t}\n\t\twarn(`[Report] {player.Name} reported {target.Name}: {reason}`)\n\t\tlocal store = reportStore\n\t\tif store then\n\t\t\ttask.spawn(pcall, function()\n\t\t\t\tstore:SetAsync(`{os.time()}_{player.UserId}`, report)\n\t\t\tend)\n\t\tend\n\t\tsystemMessage(\n\t\t\t\"Thanks - your report was sent. For anything serious, also report them in Roblox's menu (\226\152\176 \226\134\146 Report).\",\n\t\t\t\"system\",\n\t\t\t{ player }\n\t\t)\n\t\treturn\n\tend\n\n\tif kind == \"like\" or kind == \"dislike\" then\n\t\t-- Everyone but the drawer can rate each drawing once.\n\t\tif state.phase ~= \"Drawing\" or player == state.drawer or state.rated[player] then\n\t\t\treturn\n\t\tend\n\t\tstate.rated[player] = true\n\t\tsystemMessage(\n\t\t\tif kind == \"like\" then `{player.DisplayName} liked the drawing!` else `{player.DisplayName} disliked the drawing!`,\n\t\t\tkind\n\t\t)\n\t\treturn\n\tend\n\n\tif kind == \"kick\" and typeof(targetUserId) == \"number\" then\n\t\tlocal target = Players:GetPlayerByUserId(targetUserId)\n\t\tif not target or target == player then\n\t\t\treturn\n\t\tend\n\t\tlocal votes = kickVotes[target] or {}\n\t\tkickVotes[target] = votes\n\t\tif votes[player] then\n\t\t\treturn\n\t\tend\n\t\tvotes[player] = true\n\t\tlocal count = 0\n\t\tfor voter in votes do\n\t\t\tif voter.Parent == Players then\n\t\t\t\tcount += 1\n\t\t\tend\n\t\tend\n\t\tlocal needed = kickVotesNeeded()\n\t\tsystemMessage(`{player.DisplayName} is voting to kick {target.DisplayName} ({count}/{needed})`, \"kick\")\n\t\tif count >= needed then\n\t\t\tkickedUserIds[target.UserId] = true\n\t\t\tsystemMessage(`{target.DisplayName} was kicked!`, \"kick\")\n\t\t\ttarget:Kick(\"You were vote-kicked from this server.\")\n\t\tend\n\tend\nend)\n\n-- Word themes --------------------------------------------------------------------------\n\nThemeEvent.OnServerEvent:Connect(function(player, themeId)\n\tif typeof(themeId) ~= \"string\" or not Themes.byId[themeId] then\n\t\treturn\n\tend\n\tplayerThemes[player] = themeId\n\tStateEvent:FireClient(player, buildSnapshot(player))\nend)\n\n-- Robux shop --------------------------------------------------------------------------\n\n-- Buying an item gives the player a credit, which is used straight away if it can\n-- be. If not (say the turn ended while they were paying), it's kept for later in\n-- this server, so nobody pays for nothing.\n\nlocal PRODUCT_ITEMS: { [number]: string } = {}\nfor item, product in Config.PRODUCTS do\n\tif product.id ~= 0 then\n\t\tPRODUCT_ITEMS[product.id] = item\n\tend\nend\n\nlocal function notify(player: Player, text: string)\n\tsystemMessage(text, \"system\", { player })\nend\n\nlocal function addCredit(player: Player, item: string)\n\tlocal mine = credits[player] or {}\n\tcredits[player] = mine\n\tmine[item] = (mine[item] or 0) + 1\nend\n\n-- Can `item` be used by `player` right now? If not, says why.\nlocal function canUse(player: Player, item: string): (boolean, string?)\n\tif item == \"customWord\" then\n\t\tif player ~= state.drawer or state.phase ~= \"Choosing\" or state.word then\n\t\t\treturn false, \"Custom words can be bought when it's your turn to pick a word.\"\n\t\tend\n\t\treturn true\n\tend\n\tif state.phase ~= \"Drawing\" or not isPresent(state.drawer) then\n\t\treturn false, \"Use that while someone is drawing.\"\n\tend\n\tif player == state.drawer then\n\t\treturn false, \"You can't use that on your own drawing.\"\n\tend\n\tif item == \"instaGuess\" and state.guessed[player] then\n\t\treturn false, \"You already guessed this one.\"\n\tend\n\treturn true\nend\n\n-- Gives the drawer extra time to buy and type a custom word (once per turn).\nlocal function giveCustomWordTime()\n\tif not state.customTimeGiven then\n\t\tstate.customTimeGiven = true\n\t\tstate.phaseEndsAt = math.max(state.phaseEndsAt, now() + Config.CUSTOM_WORD_TIME)\n\t\tbroadcastState()\n\tend\nend\n\n-- Uses one of the player's credits for `item`. Returns whether it was used and,\n-- if not, why.\nlocal function useItem(player: Player, item: string): (boolean, string?)\n\tlocal mine = credits[player]\n\tif not mine or (mine[item] or 0) < 1 then\n\t\treturn false\n\tend\n\tlocal usable, why = canUse(player, item)\n\tif not usable then\n\t\treturn false, `{why} It's saved for later.`\n\tend\n\n\tif item == \"customWord\" then\n\t\t-- The credit is spent once a word is accepted; for now, open the form.\n\t\tstate.customUnlocked = \"credit\"\n\t\tgiveCustomWordTime()\n\t\tWordChoiceEvent:FireClient(player, { custom = true })\n\t\treturn true\n\tend\n\n\tmine[item] -= 1\n\tif item == \"instaGuess\" then\n\t\tsystemMessage(`\226\154\161 {player.DisplayName} used Insta Guess!`, \"power\")\n\t\tawardGuess(player)\n\telseif item == \"nuke\" then\n\t\tclearCanvas()\n\t\tShopEvent:FireAllClients(\"nuke\")\n\t\tsystemMessage(`\240\159\146\165 {player.DisplayName} nuked the drawing!`, \"power\")\n\telseif item == \"steal\" then\n\t\tlocal victim = state.drawer :: Player\n\t\tstate.drawer = player\n\t\tstate.guessed[player] = nil\n\t\tstate.guessed[victim] = true -- they know the word, so now they just watch and chat\n\t\tsystemMessage(`\240\159\166\185 {player.DisplayName} stole the drawing from {victim.DisplayName}!`, \"power\")\n\tend\n\tbroadcastState()\n\treturn true\nend\n\nShopEvent.OnServerEvent:Connect(function(player, item)\n\tlocal product = if typeof(item) == \"string\" then Config.PRODUCTS[item] else nil\n\tif not product then\n\t\treturn\n\tend\n\t-- Already paid for a custom word this turn: just reopen the form.\n\tif item == \"customWord\" and state.customUnlocked and player == state.drawer and state.phase == \"Choosing\" then\n\t\tWordChoiceEvent:FireClient(player, { custom = true })\n\t\treturn\n\tend\n\t-- Has one saved? Use it instead of buying another.\n\tif credits[player] and (credits[player][item] or 0) > 0 then\n\t\tlocal used, why = useItem(player, item)\n\t\tif not used and why then\n\t\t\tnotify(player, why)\n\t\tend\n\t\treturn\n\tend\n\t-- Don't charge for something that can't be used right now.\n\tlocal usable, why = canUse(player, item)\n\tif not usable then\n\t\tnotify(player, why :: string)\n\t\treturn\n\tend\n\tif item == \"customWord\" then\n\t\tgiveCustomWordTime() -- the purchase window takes a few seconds\n\tend\n\tif product.id == 0 then\n\t\tif RunService:IsStudio() then\n\t\t\t-- Not set up yet: free while testing in Studio.\n\t\t\taddCredit(player, item)\n\t\t\tuseItem(player, item)\n\t\telse\n\t\t\tnotify(player, \"That isn't for sale yet.\")\n\t\tend\n\t\treturn\n\tend\n\tMarketplaceService:PromptProductPurchase(player, product.id)\nend)\n\n-- Roblox calls this once a purchase is paid for (again, if the server didn't confirm).\nlocal processedPurchases: { [string]: boolean } = {}\nMarketplaceService.ProcessReceipt = function(receipt)\n\tif processedPurchases[receipt.PurchaseId] then\n\t\treturn Enum.ProductPurchaseDecision.PurchaseGranted\n\tend\n\tlocal item = PRODUCT_ITEMS[receipt.ProductId]\n\tlocal player = Players:GetPlayerByUserId(receipt.PlayerId)\n\tif not item or not player then\n\t\treturn Enum.ProductPurchaseDecision.NotProcessedYet -- try again when they're back\n\tend\n\tprocessedPurchases[receipt.PurchaseId] = true\n\taddCredit(player, item)\n\tlocal used, why = useItem(player, item)\n\tif not used then\n\t\tnotify(player, why or \"Saved for later!\")\n\tend\n\tbroadcastState()\n\treturn Enum.ProductPurchaseDecision.PurchaseGranted\nend\n\n-- Players ----------------------------------------------------------------------------\n\nlocal function onPlayerAdded(player: Player)\n\tif kickedUserIds[player.UserId] then\n\t\tplayer:Kick(\"You were vote-kicked from this server.\")\n\t\treturn\n\tend\n\tlocal stats = Instance.new(\"Folder\")\n\tstats.Name = \"leaderstats\"\n\tlocal score = Instance.new(\"IntValue\")\n\tscore.Name = \"Score\"\n\tscore.Parent = stats\n\tlocal wins = Instance.new(\"IntValue\")\n\twins.Name = \"Wins\"\n\twins.Parent = stats\n\tstats.Parent = player\n\n\tscores[player] = 0\n\tallTimeWins[player] = 0\n\tsystemMessage(`{player.DisplayName} joined the room!`, \"join\")\n\tbroadcastState()\n\ttask.spawn(loadWins, player)\nend\n\nPlayers.PlayerAdded:Connect(onPlayerAdded)\nfor _, player in Players:GetPlayers() do\n\tonPlayerAdded(player)\nend\n\nPlayers.PlayerRemoving:Connect(function(player)\n\tif scores[player] == nil then\n\t\treturn -- turned away on joining (vote-kicked earlier), so never really joined\n\tend\n\tsystemMessage(`{player.DisplayName} left the room!`, \"leave\")\n\tscores[player] = nil\n\tallTimeWins[player] = nil\n\treadyPlayers[player] = nil\n\tdrawRate[player] = nil\n\tlastFillAt[player] = nil\n\tcredits[player] = nil\n\tplayerThemes[player] = nil\n\tlastReportAt[player] = nil\n\tstate.rated[player] = nil\n\t-- Votes against or by a player who leaves no longer count.\n\tkickVotes[player] = nil\n\tfor _, votes in kickVotes do\n\t\tvotes[player] = nil\n\tend\n\tlastGuessAt[player] = nil\n\tstate.guessed[player] = nil\n\tstate.turnPoints[player] = nil\n\ttask.defer(broadcastState)\nend)\n"); put(client,"Main","LocalScript","-- Builds the game screen, lets the drawer draw (streaming strokes to the server),\n-- shows everyone else the drawing live, and handles guessing/chat. The look follows\n-- skribbl.io; colours and fonts are in Theme, building blocks in Ui, sounds in\n-- Sounds, and confetti/floating text in Effects.\n\nlocal GuiService = game:GetService(\"GuiService\")\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal StarterGui = game:GetService(\"StarterGui\")\nlocal UserInputService = game:GetService(\"UserInputService\")\n\nlocal Config = require(ReplicatedStorage:WaitForChild(\"GuessAndDraw\"):WaitForChild(\"Config\"))\nlocal Themes = require(ReplicatedStorage:WaitForChild(\"GuessAndDraw\"):WaitForChild(\"Themes\"))\nlocal CanvasRenderer = require(script.Parent:WaitForChild(\"CanvasRenderer\"))\nlocal ColorPicker = require(script.Parent:WaitForChild(\"ColorPicker\"))\nlocal Effects = require(script.Parent:WaitForChild(\"Effects\"))\nlocal Sounds = require(script.Parent:WaitForChild(\"Sounds\"))\nlocal Theme = require(script.Parent:WaitForChild(\"Theme\"))\nlocal Ui = require(script.Parent:WaitForChild(\"Ui\"))\n\nlocal make, label, title = Ui.make, Ui.label, Ui.title\n\nlocal Remotes = ReplicatedStorage:WaitForChild(\"GuessAndDrawRemotes\")\nlocal StateEvent = Remotes:WaitForChild(\"State\") :: RemoteEvent\nlocal DrawEvent = Remotes:WaitForChild(\"Draw\") :: RemoteEvent\nlocal CanvasEvent = Remotes:WaitForChild(\"Canvas\") :: RemoteEvent\nlocal ChatEvent = Remotes:WaitForChild(\"Chat\") :: RemoteEvent\nlocal GuessEvent = Remotes:WaitForChild(\"Guess\") :: RemoteEvent\nlocal WordChoiceEvent = Remotes:WaitForChild(\"WordChoice\") :: RemoteEvent\nlocal VoteEvent = Remotes:WaitForChild(\"Vote\") :: RemoteEvent\nlocal ShopEvent = Remotes:WaitForChild(\"Shop\") :: RemoteEvent\nlocal ThemeEvent = Remotes:WaitForChild(\"Theme\") :: RemoteEvent\n\n-- The Robux symbol, which Roblox's fonts draw at this code point.\nlocal ROBUX = utf8.char(0xE002)\n\n-- Live prices from Roblox (they can change with Managed pricing); Config's price\n-- is shown until the real one arrives, or if it can't be looked up.\nlocal MarketplaceService = game:GetService(\"MarketplaceService\")\nlocal livePrices: { [string]: number } = {}\nlocal function priceOf(item: string): number\n\treturn livePrices[item] or Config.PRODUCTS[item].price\nend\nlocal priceListeners: { () -> () } = {}\nfor item, product in Config.PRODUCTS do\n\tif product.id ~= 0 then\n\t\ttask.spawn(function()\n\t\t\tlocal ok, info = pcall(function()\n\t\t\t\treturn MarketplaceService:GetProductInfo(product.id, Enum.InfoType.Product)\n\t\t\tend)\n\t\t\tif ok and info and typeof(info.PriceInRobux) == \"number\" then\n\t\t\t\tlivePrices[item] = info.PriceInRobux\n\t\t\t\tfor _, listener in priceListeners do\n\t\t\t\t\tlistener()\n\t\t\t\tend\n\t\t\tend\n\t\tend)\n\tend\nend\n\nlocal player = Players.LocalPlayer\n\n-- Guesses go through this game's own chat box, so hide Roblox's chat to keep\n-- answers out of it.\ntask.spawn(function()\n\tfor _ = 1, 10 do\n\t\tlocal ok = pcall(function()\n\t\t\tStarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, false)\n\t\t\tStarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, false)\n\t\tend)\n\t\tif ok then\n\t\t\tbreak\n\t\tend\n\t\ttask.wait(1)\n\tend\nend)\n\nlocal function clearChildren(parent: Instance)\n\tfor _, child in parent:GetChildren() do\n\t\tif child:IsA(\"GuiObject\") then\n\t\t\tchild:Destroy()\n\t\tend\n\tend\nend\n\nlocal function escapeRichText(text: string): string\n\ttext = string.gsub(text, \"&\", \"&amp;\")\n\ttext = string.gsub(text, \"<\", \"&lt;\")\n\ttext = string.gsub(text, \">\", \"&gt;\")\n\treturn text\nend\n\nlocal function colorTag(color: Color3, text: string): string\n\treturn `<font color=\"#{color:ToHex()}\">{text}</font>`\nend\n\n-- Each letter in a different colour, like the skribbl.io logo.\nlocal function rainbowText(text: string): string\n\tlocal parts = {}\n\tlocal index = 0\n\tfor _, code in utf8.codes(text) do\n\t\tlocal char = utf8.char(code)\n\t\tif char == \" \" then\n\t\t\ttable.insert(parts, \" \")\n\t\telse\n\t\t\tindex += 1\n\t\t\ttable.insert(parts, colorTag(Theme.rainbow[(index - 1) % #Theme.rainbow + 1], escapeRichText(char)))\n\t\tend\n\tend\n\treturn table.concat(parts)\nend\n\n-- Screen & background ---------------------------------------------------------------\n\nlocal screen = make(\"ScreenGui\", {\n\tName = \"GuessAndDraw\",\n\tResetOnSpawn = false,\n\t-- Cover the whole window, behind Roblox's topbar too, so the background fills it.\n\tIgnoreGuiInset = true,\n\tZIndexBehavior = Enum.ZIndexBehavior.Sibling,\n\tParent = player:WaitForChild(\"PlayerGui\"),\n})\n\nlocal background = make(\"Frame\", {\n\tName = \"Background\",\n\tSize = UDim2.fromScale(1, 1),\n\tBackgroundColor3 = Theme.background,\n\tBorderSizePixel = 0,\n\tClipsDescendants = true,\n\tZIndex = 0,\n\tParent = screen,\n})\n\n-- The background takes the colours of the current word theme. With the doodle\n-- lines uploaded (white on see-through), they're tinted per theme over a plain\n-- colour; without them, the green tile shows for the General theme only.\nlocal doodles = Config.BACKGROUND_DOODLES ~= \"\"\nlocal tile = Config.BACKGROUND_TILE_SIZE\nlocal backgroundImage: ImageLabel? = nil\n-- Off for themes marked `still` (Halloween's bold lines on bright orange make the\n-- 1-pixel hops easy to see).\nlocal startingTheme = Themes.byId[Config.DEFAULT_THEME]\nlocal backgroundSliding = not (startingTheme and startingTheme.still)\nif doodles or Config.BACKGROUND_TILE ~= \"\" then\n\tlocal image = make(\"ImageLabel\", {\n\t\t-- One tile larger than the screen so it can scroll seamlessly.\n\t\tSize = UDim2.new(1, tile, 1, tile),\n\t\tBackgroundTransparency = 1,\n\t\tImage = if doodles then Config.BACKGROUND_DOODLES else Config.BACKGROUND_TILE,\n\t\tScaleType = Enum.ScaleType.Tile,\n\t\tTileSize = UDim2.fromOffset(tile, tile),\n\t\tParent = background,\n\t})\n\tbackgroundImage = image\n\tif Config.BACKGROUND_SCROLL_SPEED > 0 then\n\t\t-- Roblox draws GUI at whole pixels, so the drift is a series of 1-pixel hops.\n\t\t-- Timing each hop by the clock lets frame-time wobble space them unevenly\n\t\t-- (4 frames, then 6, then 5...), which reads as a judder on bold lines. So hop\n\t\t-- every N frames instead, with N worked out from the smoothed frame rate: the\n\t\t-- hops come at an even beat and the speed still matches the setting.\n\t\tlocal framesPerSecond = 60\n\t\tlocal framesSinceHop = 0\n\t\tlocal offset = 0\n\t\tRunService.RenderStepped:Connect(function(dt)\n\t\t\tframesPerSecond += (1 / math.max(dt, 1 / 360) - framesPerSecond) * 0.02\n\t\t\tif not backgroundSliding then\n\t\t\t\treturn\n\t\t\tend\n\t\t\tframesSinceHop += 1\n\t\t\tif framesSinceHop >= math.max(1, math.round(framesPerSecond / Config.BACKGROUND_SCROLL_SPEED)) then\n\t\t\t\tframesSinceHop = 0\n\t\t\t\toffset = (offset + 1) % tile\n\t\t\t\timage.Position = UDim2.fromOffset(-offset, -offset)\n\t\t\tend\n\t\tend)\n\tend\nend\n\nlocal shownTheme: string? = nil\nlocal applyThemeToOverlay: (Themes.Theme) -> () = function() end\n\nlocal function applyTheme(themeId: string)\n\tif themeId == shownTheme then\n\t\treturn\n\tend\n\tshownTheme = themeId\n\tlocal theme = Themes.byId[themeId] or Themes.byId.general\n\tbackgroundSliding = not theme.still\n\tUi.tween(background, 0.8, { BackgroundColor3 = theme.background })\n\tlocal image = backgroundImage\n\tif image then\n\t\tif doodles then\n\t\t\tUi.tween(image, 0.8, { ImageColor3 = theme.doodles, ImageTransparency = 0 })\n\t\telse\n\t\t\t-- Only the green tile is available: show it for General, plain colour otherwise.\n\t\t\tUi.tween(image, 0.8, { ImageTransparency = if theme.id == \"general\" then 0 else 1 })\n\t\tend\n\tend\n\tapplyThemeToOverlay(theme)\nend\n\nlocal root = make(\"Frame\", {\n\tSize = UDim2.fromScale(1, 1),\n\tBackgroundTransparency = 1,\n\tZIndex = 1,\n\tParent = screen,\n})\n\nlocal effectsLayer = make(\"Frame\", {\n\tName = \"Effects\",\n\tSize = UDim2.fromScale(1, 1),\n\tBackgroundTransparency = 1,\n\tZIndex = 10,\n\tParent = screen,\n})\nEffects.init(effectsLayer)\n\n-- The whole game sits in one box laid out with skribbl.io's own measurements (in\n-- pixels at 1870 wide), then zoomed as a whole to fill the window's width, or its\n-- height if that runs out first, so everything keeps the same proportions and\n-- spacing on any screen. `box` turns design-pixel rectangles into positions and\n-- sizes inside it.\nlocal DESIGN = Vector2.new(1870, 1086)\nlocal MARGIN = 10\n-- At most this share of the window's width, so background shows at the sides.\nlocal MAX_WIDTH_SHARE = 0.82\n\nlocal game_ = make(\"Frame\", {\n\tName = \"Game\",\n\tAnchorPoint = Vector2.new(0.5, 0),\n\tSize = UDim2.fromOffset(DESIGN.X, DESIGN.Y),\n\tBackgroundTransparency = 1,\n\tParent = root,\n})\nlocal gameScale = make(\"UIScale\", { Parent = game_ })\n\n-- Height of Roblox's topbar (menu buttons). It can be 0 for a moment while the\n-- game loads, so this is re-checked whenever it changes.\nlocal function topInset(): number\n\tlocal inset = GuiService:GetGuiInset().Y\n\tpcall(function()\n\t\tinset = math.max(inset, GuiService.TopbarInset.Height)\n\tend)\n\treturn inset\nend\n\nlocal function fitToScreen()\n\tlocal inset = topInset()\n\tlocal available = screen.AbsoluteSize - Vector2.new(MARGIN * 2, inset + MARGIN * 2)\n\tlocal width = math.min(available.X, screen.AbsoluteSize.X * MAX_WIDTH_SHARE)\n\tgameScale.Scale = math.clamp(math.min(width / DESIGN.X, available.Y / DESIGN.Y), 0.1, 2)\n\t-- Centred left to right, pinned to the top just below Roblox's topbar.\n\tgame_.Position = UDim2.new(0.5, 0, 0, inset + MARGIN)\nend\n\nscreen:GetPropertyChangedSignal(\"AbsoluteSize\"):Connect(fitToScreen)\npcall(function()\n\tGuiService:GetPropertyChangedSignal(\"TopbarInset\"):Connect(fitToScreen)\nend)\nfitToScreen()\n\n-- Roblox's automatic sizing (AutomaticCanvasSize / AutomaticSize) miscounts inside\n-- the zoomed game area, which left the newest chat messages below the bottom of\n-- the scroll area, out of sight. So scrolling lists are sized by hand: measure the\n-- content, undo the zoom, and set the size. `onSized` runs after each resize.\nlocal function sizeToContent(layout: UIListLayout, target: GuiObject, extra: number, onSized: ((number) -> ())?)\n\tlocal function update()\n\t\tlocal height = layout.AbsoluteContentSize.Y / gameScale.Scale + extra\n\t\tif target:IsA(\"ScrollingFrame\") then\n\t\t\ttarget.CanvasSize = UDim2.fromOffset(0, height)\n\t\telse\n\t\t\ttarget.Size = UDim2.new(1, 0, 0, height)\n\t\tend\n\t\tif onSized then\n\t\t\tonSized(height)\n\t\tend\n\tend\n\tlayout:GetPropertyChangedSignal(\"AbsoluteContentSize\"):Connect(update)\n\tgameScale:GetPropertyChangedSignal(\"Scale\"):Connect(update)\n\ttask.defer(update)\nend\n\nlocal function box(x: number, y: number, width: number, height: number): (UDim2, UDim2)\n\treturn UDim2.fromScale(x / DESIGN.X, y / DESIGN.Y), UDim2.fromScale(width / DESIGN.X, height / DESIGN.Y)\nend\n\n-- Logo -----------------------------------------------------------------------------------\n\nlocal LOGO_TEXT = \"Guess & Draw\"\nlocal logoPosition, logoSize = box(0, 0, 430, 64)\nlocal logo = make(\"Frame\", {\n\tPosition = logoPosition,\n\tSize = logoSize,\n\tBackgroundTransparency = 1,\n\tParent = game_,\n})\n-- A dark copy behind the letters gives the chunky drop shadow.\nlocal logoShadowOutline = Ui.textOutline(3, Theme.outline)\nlocal logoOutline = Ui.textOutline(3, Theme.outline)\nlocal logoShadow = label({\n\tPosition = UDim2.fromOffset(3, 4),\n\tSize = UDim2.fromScale(0.86, 1),\n\tText = LOGO_TEXT,\n\tFontFace = Theme.logo,\n\tTextColor3 = Theme.outline,\n\tTextTransparency = 0.35,\n\tTextXAlignment = Enum.TextXAlignment.Left,\n\tParent = logo,\n}, { logoShadowOutline })\nlocal logoLetters = label({\n\tSize = UDim2.fromScale(0.86, 1),\n\tRichText = true,\n\tText = rainbowText(LOGO_TEXT),\n\tFontFace = Theme.logo,\n\tTextXAlignment = Enum.TextXAlignment.Left,\n\tParent = logo,\n}, { logoOutline })\nlocal logoPencil = Ui.pencil({\n\tAnchorPoint = Vector2.new(0.5, 0.5),\n\tPosition = UDim2.fromScale(0.92, 0.5),\n\tSize = UDim2.fromScale(0.12, 1.1),\n\tRotation = 23,\n\tOutlineThickness = 3,\n\tParent = logo,\n})\n\n-- Like skribbl.io's logo, it doesn't glide: it flicks between two slightly\n-- different drawings (thicker outline, nudged a pixel) a few times a second, so it\n-- looks hand-drawn and alive.\ntask.spawn(function()\n\tlocal alternate = false\n\twhile true do\n\t\ttask.wait(0.32)\n\t\talternate = not alternate\n\t\tlogoOutline.Thickness = if alternate then 4.5 else 3\n\t\tlogoShadowOutline.Thickness = logoOutline.Thickness\n\t\tlogoLetters.Position = if alternate then UDim2.fromOffset(1, -1) else UDim2.new()\n\t\tlogoShadow.Position = if alternate then UDim2.fromOffset(4, 4) else UDim2.fromOffset(3, 4)\n\t\tlogoPencil.Rotation = if alternate then 27 else 23\n\tend\nend)\n\n-- Top bar: alarm clock, round, word, sound toggle ----------------------------------------\n\nlocal topPosition, topSize = box(0, 70, 1870, 68)\nlocal topBar = Ui.panel({ Position = topPosition, Size = topSize, Parent = game_ })\n\n-- skribbl.io's alarm clock: grey bells, a thick black ring and little legs, and a\n-- bit bigger than the bar so it pokes out above and below.\nlocal clock = make(\"Frame\", {\n\tAnchorPoint = Vector2.new(0, 0.5),\n\tPosition = UDim2.new(0, 2, 0.5, 0),\n\tSize = UDim2.fromScale(1, 1.12),\n\tBackgroundTransparency = 1,\n\tParent = topBar,\n}, { Ui.square() })\n\nmake(\"Frame\", { -- the knob between the bells\n\tAnchorPoint = Vector2.new(0.5, 0.5),\n\tPosition = UDim2.fromScale(0.5, 0.09),\n\tSize = UDim2.fromScale(0.08, 0.07),\n\tBackgroundColor3 = Theme.outline,\n\tZIndex = 1,\n\tParent = clock,\n}, { Ui.corner(2) })\nfor _, side in { -1, 1 } do\n\tmake(\"Frame\", { -- bell\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.fromScale(0.5 + side * 0.25, 0.15),\n\t\tSize = UDim2.fromScale(0.32, 0.2),\n\t\tRotation = side * 35,\n\t\tBackgroundColor3 = Color3.fromRGB(150, 150, 150),\n\t\tZIndex = 1,\n\t\tParent = clock,\n\t}, { Ui.round(), Ui.border(3, Theme.outline) })\n\tmake(\"Frame\", { -- leg\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.fromScale(0.5 + side * 0.24, 0.92),\n\t\tSize = UDim2.fromScale(0.06, 0.13),\n\t\tRotation = side * -40,\n\t\tBackgroundColor3 = Theme.outline,\n\t\tZIndex = 1,\n\t\tParent = clock,\n\t}, { Ui.round() })\nend\n\nlocal clockFace = make(\"Frame\", {\n\tAnchorPoint = Vector2.new(0.5, 0.5),\n\tPosition = UDim2.fromScale(0.5, 0.55),\n\tSize = UDim2.fromScale(0.76, 0.76),\n\tBackgroundColor3 = Theme.white,\n\tZIndex = 2,\n\tParent = clock,\n}, { Ui.round(), Ui.border(4, Theme.outline) })\n\nlocal timerLabel = label({\n\tSize = UDim2.fromScale(1, 1),\n\tFontFace = Theme.heavy,\n\tText = \"\",\n\tParent = clockFace,\n}, { Ui.pad(8) })\n\nlocal roundLabel = label({\n\tPosition = UDim2.fromScale(0.045, 0.06),\n\tSize = UDim2.fromScale(0.25, 0.54),\n\tFontFace = Theme.bold,\n\tText = \"\",\n\tTextXAlignment = Enum.TextXAlignment.Left,\n\tParent = topBar,\n}, { Ui.maxText(30) })\n\n-- Which word theme this turn uses, under the round.\nlocal themeLabel = label({\n\tPosition = UDim2.fromScale(0.045, 0.58),\n\tSize = UDim2.fromScale(0.25, 0.36),\n\tFontFace = Theme.bold,\n\tText = \"\",\n\tTextColor3 = Theme.muted,\n\tTextXAlignment = Enum.TextXAlignment.Left,\n\tParent = topBar,\n}, { Ui.maxText(20) })\n\nlocal wordArea = make(\"Frame\", {\n\tAnchorPoint = Vector2.new(0.5, 0),\n\tPosition = UDim2.fromScale(0.5, 0),\n\tSize = UDim2.fromScale(0.44, 1),\n\tBackgroundTransparency = 1,\n\tParent = topBar,\n})\n\nlocal wordCaption = label({\n\tPosition = UDim2.fromScale(0, 0.08),\n\tSize = UDim2.fromScale(1, 0.3),\n\tFontFace = Theme.mono,\n\tText = \"\",\n\tParent = wordArea,\n}, { Ui.maxText(20) })\n\n-- The word, one letter per box like skribbl.io: hidden letters are just an\n-- underline, and each word's letter count sits raised at the end.\nlocal wordRow = make(\"Frame\", {\n\tPosition = UDim2.fromScale(0, 0.4),\n\tSize = UDim2.fromScale(1, 0.52),\n\tBackgroundTransparency = 1,\n\tParent = wordArea,\n}, {\n\tmake(\"UIListLayout\", {\n\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\tHorizontalAlignment = Enum.HorizontalAlignment.Center,\n\t\tVerticalAlignment = Enum.VerticalAlignment.Bottom,\n\t\tPadding = UDim.new(0, 5),\n\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t}),\n})\n\nlocal shownWord: string? = nil\nlocal function setWord(word: string?, hidden: boolean, color: Color3)\n\tlocal key = if word then `{word}|{hidden}|{color:ToHex()}` else nil\n\tif key == shownWord then\n\t\treturn\n\tend\n\tshownWord = key\n\tfor _, child in wordRow:GetChildren() do\n\t\tif child:IsA(\"GuiObject\") then\n\t\t\tchild:Destroy()\n\t\tend\n\tend\n\tif not word then\n\t\treturn\n\tend\n\tlocal counts, current = {}, 0\n\tfor i = 1, #word do\n\t\tlocal char = string.sub(word, i, i)\n\t\tif char == \" \" then\n\t\t\tmake(\"Frame\", { Size = UDim2.fromOffset(16, 1), BackgroundTransparency = 1, LayoutOrder = i, Parent = wordRow })\n\t\t\ttable.insert(counts, current)\n\t\t\tcurrent = 0\n\t\telse\n\t\t\tcurrent += 1\n\t\t\tlocal cell = label({\n\t\t\t\tSize = UDim2.new(0, 20, 1, 0),\n\t\t\t\tText = if char == \"_\" then \"\" else char,\n\t\t\t\tFontFace = Theme.monoBold,\n\t\t\t\tTextScaled = false,\n\t\t\t\tTextSize = 30,\n\t\t\t\tTextColor3 = color,\n\t\t\t\tTextYAlignment = Enum.TextYAlignment.Bottom,\n\t\t\t\tLayoutOrder = i,\n\t\t\t\tParent = wordRow,\n\t\t\t})\n\t\t\tif hidden then\n\t\t\t\tmake(\"Frame\", {\n\t\t\t\t\tAnchorPoint = Vector2.new(0, 1),\n\t\t\t\t\tPosition = UDim2.new(0, 0, 1, 2),\n\t\t\t\t\tSize = UDim2.new(1, 0, 0, 3),\n\t\t\t\t\tBackgroundColor3 = Theme.text,\n\t\t\t\t\tBorderSizePixel = 0,\n\t\t\t\t\tParent = cell,\n\t\t\t\t})\n\t\t\tend\n\t\tend\n\tend\n\ttable.insert(counts, current)\n\tlabel({\n\t\tSize = UDim2.fromScale(0, 1),\n\t\tAutomaticSize = Enum.AutomaticSize.X,\n\t\tText = table.concat(counts, \" \"),\n\t\tFontFace = Theme.mono,\n\t\tTextScaled = false,\n\t\tTextSize = 18,\n\t\tTextYAlignment = Enum.TextYAlignment.Top,\n\t\tLayoutOrder = #word + 1,\n\t\tParent = wordRow,\n\t}, { make(\"UIPadding\", { PaddingLeft = UDim.new(0, 4), PaddingTop = UDim.new(0, -6) }) })\nend\n\n-- Where skribbl.io has its settings gear: a sound on/off switch.\nlocal soundButton = make(\"TextButton\", {\n\tAnchorPoint = Vector2.new(1, 0.5),\n\tPosition = UDim2.new(1, -6, 0.5, 0),\n\tSize = UDim2.fromScale(1, 0.85),\n\tBackgroundTransparency = 1,\n\tText = \"\240\159\148\138\",\n\tTextScaled = true,\n\tParent = topBar,\n}, { Ui.square() })\nUi.hoverable(soundButton)\nsoundButton.Activated:Connect(function()\n\tSounds.muted = not Sounds.muted\n\tsoundButton.Text = if Sounds.muted then \"\240\159\148\135\" else \"\240\159\148\138\"\n\tSounds.play(\"click\")\nend)\n\n-- Orange pill buttons in the top bar.\nlocal function pill(text: string, width: number, rightOffset: number): TextButton\n\tlocal button = make(\"TextButton\", {\n\t\tAnchorPoint = Vector2.new(1, 0.5),\n\t\tPosition = UDim2.new(1, -rightOffset, 0.5, 0),\n\t\tSize = UDim2.fromOffset(width, 48),\n\t\tBackgroundColor3 = Color3.fromRGB(255, 150, 30),\n\t\tAutoButtonColor = false,\n\t\tText = text,\n\t\tTextScaled = true,\n\t\tFontFace = Theme.heavy,\n\t\tTextColor3 = Theme.white,\n\t\tParent = topBar,\n\t}, { Ui.corner(10), Ui.pad(14, 9) })\n\tUi.hoverable(button)\n\treturn button\nend\n\n-- Votes to kick whoever is drawing right now (e.g. for drawing something rude).\nlocal voteKickButton = pill(\"Vote Kick: 0/2\", 230, 230)\nlocal reportButton = pill(\"Report\", 140, 78)\n\n-- Left: players ----------------------------------------------------------------------------\n\nlocal MAIN_TOP = 147\nlocal CANVAS_HEIGHT = 856 -- 4:3 of the 1141-wide canvas\n\nlocal THEME_MENU_HEIGHT = 64\nlocal playersPosition, playersSize = box(0, MAIN_TOP, 284, CANVAS_HEIGHT - THEME_MENU_HEIGHT - 10)\nlocal playersScroller = make(\"ScrollingFrame\", {\n\tPosition = playersPosition,\n\tSize = playersSize,\n\tBackgroundTransparency = 1,\n\tBorderSizePixel = 0,\n\tScrollBarThickness = 4,\n\tCanvasSize = UDim2.new(),\n\tParent = game_,\n})\n-- Like skribbl.io's, the list is one white card with rounded corners, only as tall\n-- as its rows (the small padding keeps the rows inside the rounded corners).\nlocal playersLayout = make(\"UIListLayout\", { SortOrder = Enum.SortOrder.LayoutOrder })\nlocal playersList = Ui.panel({\n\tSize = UDim2.fromScale(1, 0),\n\tParent = playersScroller,\n}, {\n\tplayersLayout,\n\tmake(\"UIPadding\", { PaddingTop = UDim.new(0, 5), PaddingBottom = UDim.new(0, 5) }),\n})\n-- The card is as tall as its rows (plus its padding), and the scroller fits the card.\nsizeToContent(playersLayout, playersList, 10, function(height)\n\tplayersScroller.CanvasSize = UDim2.fromOffset(0, height)\nend)\nplayersList:FindFirstChildOfClass(\"UICorner\").CornerRadius = UDim.new(0, 7)\n\n-- \"Your theme\" menu under the player list: the words you get, and everyone's\n-- background colour, when it's your turn to draw.\nlocal themeMenuPosition, themeMenuSize = box(0, MAIN_TOP + CANVAS_HEIGHT - THEME_MENU_HEIGHT, 284, THEME_MENU_HEIGHT)\nlocal themeButton = make(\"TextButton\", {\n\tPosition = themeMenuPosition,\n\tSize = themeMenuSize,\n\tBackgroundColor3 = Theme.white,\n\tAutoButtonColor = false,\n\tText = \"\",\n\tParent = game_,\n}, { Ui.corner(7) })\nlabel({\n\tPosition = UDim2.fromOffset(12, 5),\n\tSize = UDim2.new(1, -24, 0, 20),\n\tText = \"YOUR THEME\",\n\tTextScaled = false,\n\tTextSize = 15,\n\tFontFace = Theme.mono,\n\tTextColor3 = Theme.muted,\n\tTextXAlignment = Enum.TextXAlignment.Left,\n\tParent = themeButton,\n})\nlocal themeButtonText = label({\n\tPosition = UDim2.fromOffset(12, 26),\n\tSize = UDim2.new(1, -52, 0, 30),\n\tText = \"\",\n\tTextScaled = false,\n\tTextSize = 22,\n\tTextXAlignment = Enum.TextXAlignment.Left,\n\tTextTruncate = Enum.TextTruncate.AtEnd,\n\tParent = themeButton,\n})\n-- The arrow, drawn from two bars because the font has no arrow glyph. The list\n-- opens upwards, so it points up while closed and down (to close) while open.\nlocal themeArrow = make(\"Frame\", {\n\tAnchorPoint = Vector2.new(0.5, 0.5),\n\tPosition = UDim2.new(1, -26, 0, 41),\n\tSize = UDim2.fromOffset(18, 18),\n\tRotation = 180,\n\tBackgroundTransparency = 1,\n\tParent = themeButton,\n})\nfor _, side in { -1, 1 } do\n\tmake(\"Frame\", {\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.new(0.5, side * 4, 0.5, 0),\n\t\tSize = UDim2.fromOffset(12, 4),\n\t\tRotation = side * -45,\n\t\tBackgroundColor3 = Theme.text,\n\t\tParent = themeArrow,\n\t}, { Ui.corner(2) })\nend\nUi.hoverable(themeButton)\n\nlocal themeList = Ui.panel({\n\tAnchorPoint = Vector2.new(0, 1),\n\tPosition = UDim2.fromOffset(0, MAIN_TOP + CANVAS_HEIGHT - THEME_MENU_HEIGHT - 8),\n\tSize = UDim2.fromOffset(330, 16 + #Themes.list 