d\n\nlocal function openReportMenu()\n\tlocal s = snapshot\n\tif reportMenu.Visible or not s then\n\t\tcloseReportMenu()\n\t\treturn\n\tend\n\tlocal options = {}\n\tfor _, entry in s.players do\n\t\tif entry.userId ~= player.UserId then\n\t\t\ttable.insert(options, {\n\t\t\t\ttext = entry.name,\n\t\t\t\tpick = function()\n\t\t\t\t\tlocal reasons = {}\n\t\t\t\t\tfor _, reason in REPORT_REASONS do\n\t\t\t\t\t\ttable.insert(reasons, {\n\t\t\t\t\t\t\ttext = reason,\n\t\t\t\t\t\t\tpick = function()\n\t\t\t\t\t\t\t\tVoteEvent:FireServer(\"report\", entry.userId, reason)\n\t\t\t\t\t\t\t\tSounds.play(\"click\")\n\t\t\t\t\t\t\t\tcloseReportMenu()\n\t\t\t\t\t\t\tend,\n\t\t\t\t\t\t})\n\t\t\t\t\tend\n\t\t\t\t\ttable.insert(reasons, { text = \"Cancel\", color = Theme.muted, pick = closeReportMenu })\n\t\t\t\t\tfillReportMenu(`Why report {entry.name}?`, reasons)\n\t\t\t\tend,\n\t\t\t})\n\t\tend\n\tend\n\tif #options == 0 then\n\t\ttable.insert(options, { text = \"Nobody else is here yet\", pick = closeReportMenu })\n\tend\n\ttable.insert(options, { text = \"Cancel\", color = Theme.muted, pick = closeReportMenu })\n\tfillReportMenu(\"Report a player\", options)\n\treportMenu.Visible = true\n\tUi.pop(reportMenu, 0.7, 0.25)\nend\n\nreportButton.Activated:Connect(function()\n\tSounds.play(\"click\")\n\topenReportMenu()\nend)\n\nvoteKickButton.Activated:Connect(function()\n\tlocal s = snapshot\n\tif s and s.drawerUserId and not s.isDrawer and not s.votedOnDrawer then\n\t\tSounds.play(\"click\")\n\t\tVoteEvent:FireServer(\"kick\", s.drawerUserId)\n\tend\nend)\n\nkickButton.Activated:Connect(function()\n\tif kickTarget then\n\t\tVoteEvent:FireServer(\"kick\", kickTarget)\n\t\tSounds.play(\"click\")\n\tend\n\tcloseKickMenu()\nend)\n\ntype Row = {\n\tframe: Frame,\n\trank: TextLabel,\n\tname: TextLabel,\n\tscore: TextLabel,\n\tpencil: Frame,\n\tentry: any, -- the latest player info, for the kick menu\n}\n\nlocal rows: { [number]: Row } = {}\n\n-- A skribbl.io player row: rank top-left, name and points centred, avatar on the right.\nlocal function createRow(entry): Row\n\tlocal frame = make(\"Frame\", {\n\t\tSize = UDim2.new(1, 0, 0, 68),\n\t\tBackgroundColor3 = Theme.white,\n\t\tBorderSizePixel = 0,\n\t\tParent = playersList,\n\t})\n\tlocal rank = label({\n\t\tPosition = UDim2.fromOffset(9, 6),\n\t\tSize = UDim2.fromOffset(44, 26),\n\t\tTextScaled = false,\n\t\tTextSize = 23,\n\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\tText = \"\",\n\t\tParent = frame,\n\t})\n\t-- Name and points are centred in the space between the rank and the avatar.\n\tlocal name = label({\n\t\tPosition = UDim2.new(0, 44, 0, 9),\n\t\tSize = UDim2.new(1, -118, 0, 26),\n\t\tTextScaled = false,\n\t\tTextSize = 23,\n\t\tTextTruncate = Enum.TextTruncate.AtEnd,\n\t\tRichText = true,\n\t\tText = \"\",\n\t\tParent = frame,\n\t})\n\tlocal score = label({\n\t\tPosition = UDim2.new(0, 44, 0, 35),\n\t\tSize = UDim2.new(1, -118, 0, 22),\n\t\tTextScaled = false,\n\t\tTextSize = 20,\n\t\tFontFace = Theme.regular,\n\t\tText = \"\",\n\t\tParent = frame,\n\t})\n\tUi.avatar(entry.userId, entry.name, {\n\t\tAnchorPoint = Vector2.new(1, 0.5),\n\t\tPosition = UDim2.new(1, -2, 0.5, 0),\n\t\tSize = UDim2.fromOffset(66, 66),\n\t\tParent = frame,\n\t})\n\t-- skribbl.io's pencil leans against the drawer's avatar.\n\tlocal pencil = Ui.pencil({\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.new(1, -68, 0.5, 2),\n\t\tSize = UDim2.fromOffset(17, 58),\n\t\tVisible = false,\n\t\tParent = frame,\n\t})\n\tUi.pop(frame, 0.7, 0.3)\n\tlocal row = { frame = frame, rank = rank, name = name, score = score, pencil = pencil, entry = entry }\n\t-- Click anyone else's row to vote to kick them.\n\tlocal clickArea = make(\"TextButton\", {\n\t\tSize = UDim2.fromScale(1, 1),\n\t\tBackgroundTransparency = 1,\n\t\tText = \"\",\n\t\tZIndex = 5,\n\t\tParent = frame,\n\t})\n\tclickArea.Activated:Connect(function()\n\t\tlocal current = row.entry\n\t\tif current.userId ~= player.UserId then\n\t\t\tSounds.play(\"click\", 0.5)\n\t\t\topenKickMenu(current.userId, current.name, frame)\n\t\tend\n\tend)\n\treturn row\nend\n\nlocal function renderPlayers(list)\n\tlocal seen = {}\n\tfor position, entry in list do\n\t\tseen[entry.userId] = true\n\t\tlocal row = rows[entry.userId] or createRow(entry)\n\t\trows[entry.userId] = row\n\t\trow.entry = entry\n\t\tlocal isMe = entry.userId == player.UserId\n\t\trow.frame.LayoutOrder = position\n\t\trow.rank.Text = `#{position}`\n\t\t-- A small crown and the player's all-time match wins sit right after the name.\n\t\tlocal crowns = if (entry.wins or 0) > 0\n\t\t\tthen ` <font size=\"17\" color=\"#{Theme.crownText:ToHex()}\">\240\159\145\145{entry.wins}</font>`\n\t\t\telse \"\"\n\t\trow.name.Text = escapeRichText(entry.name) .. (if isMe then \" (You)\" else \"\") .. crowns\n\t\trow.name.TextColor3 = if isMe then Theme.you else Theme.text\n\t\trow.score.Text = `{entry.score} points`\n\t\trow.pencil.Visible = entry.isDrawer\n\t\tlocal bg = if entry.guessed\n\t\t\tthen Theme.guessedRow\n\t\t\telseif entry.isDrawer then Theme.drawerRow\n\t\t\telseif position % 2 == 0 then Theme.rowAlt\n\t\t\telse Theme.white\n\t\tif row.frame.BackgroundColor3 ~= bg then\n\t\t\tUi.tween(row.frame, 0.3, { BackgroundColor3 = bg })\n\t\tend\n\tend\n\tfor userId, row in rows do\n\t\tif not seen[userId] then\n\t\t\trow.frame:Destroy()\n\t\t\trows[userId] = nil\n\t\tend\n\tend\nend\n\n-- Overlay screens -----------------------------------------------------------------------------------\n\nlocal countdownLabel: TextLabel? = nil\n\nlocal function overlayHeader(titleText: string, subtitleText: string?)\n\toverlayTitle.Text = titleText\n\toverlaySubtitle.Text = subtitleText or \"\"\nend\n\n-- Shows `gui` after `delay` seconds with a springy pop.\nlocal function popLater(gui: GuiObject, delay: number, from: number?)\n\tUi.scaleOf(gui).Scale = 0\n\ttask.delay(delay, function()\n\t\tif gui.Parent then\n\t\t\tUi.pop(gui, from or 0.3)\n\t\tend\n\tend)\nend\n\nlocal function wobblingEmoji(emoji: string)\n\tlocal icon = label({\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.fromScale(0.5, 0.4),\n\t\tSize = UDim2.fromScale(0.5, 0.55),\n\t\tText = emoji,\n\t\tRotation = -12,\n\t\tParent = overlayBody,\n\t}, { Ui.maxText(96) })\n\tUi.loop(icon, 0.9, { Rotation = 12 })\nend\n\nlocal function renderWordChoices()\n\tlocal choices = wordChoices\n\tif not choices then\n\t\treturn\n\tend\n\tlocal row = make(\"Frame\", {\n\t\tPosition = UDim2.fromScale(0, 0.12),\n\t\tSize = UDim2.fromScale(1, 0.22),\n\t\tBackgroundTransparency = 1,\n\t\tParent = overlayBody,\n\t}, {\n\t\tmake(\"UIListLayout\", {\n\t\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\t\tHorizontalAlignment = Enum.HorizontalAlignment.Center,\n\t\t\tPadding = UDim.new(0.03, 0),\n\t\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t\t}),\n\t})\n\tfor index, word in choices do\n\t\tlocal choice = Ui.overlayButton({\n\t\t\tText = word,\n\t\t\tSize = UDim2.fromScale(0.24, 1),\n\t\t\tLayoutOrder = index,\n\t\t\tParent = row,\n\t\t})\n\t\tpopLater(choice, (index - 1) * 0.1)\n\t\tchoice.Activated:Connect(function()\n\t\t\tWordChoiceEvent:FireServer(index)\n\t\t\twordChoices = nil\n\t\t\tchosenWord = word\n\t\t\tclearChildren(overlayBody)\n\t\t\toverlayHeader(\"Get ready to draw!\", word)\n\t\t\twobblingEmoji(\"\226\156\143\239\184\143\")\n\t\tend)\n\tend\n\n\t-- A small lock to the side: pay to draw any word you type.\n\tlocal lock = make(\"TextButton\", {\n\t\tAnchorPoint = Vector2.new(1, 0.5),\n\t\tPosition = UDim2.fromScale(1, 0.23),\n\t\tSize = UDim2.fromScale(0.08, 0.2),\n\t\tBackgroundColor3 = Theme.white,\n\t\tBackgroundTransparency = 1,\n\t\tText = \"\240\159\148\146\",\n\t\tTextScaled = true,\n\t\tAutoButtonColor = false,\n\t\tParent = overlayBody,\n\t}, { Ui.square(), Ui.round(), Ui.border(2, Theme.white), Ui.pad(6) })\n\tlabel({\n\t\tAnchorPoint = Vector2.new(0.5, 0),\n\t\tPosition = UDim2.new(0.5, 0, 1, 4),\n\t\tSize = UDim2.fromScale(1.6, 0.4),\n\t\tText = `{ROBUX}{priceOf(\"customWord\")} Custom`,\n\t\tTextColor3 = Theme.overlayText,\n\t\tParent = lock,\n\t})\n\tpopLater(lock, #choices * 0.1)\n\tUi.hoverable(lock)\n\tlock.Activated:Connect(function()\n\t\tSounds.play(\"click\")\n\t\t-- The server asks for the Robux; the form opens once it's paid.\n\t\tShopEvent:FireServer(\"customWord\")\n\tend)\nend\n\nlocal function textField(placeholder: string, y: number): TextBox\n\treturn make(\"TextBox\", {\n\t\tAnchorPoint = Vector2.new(0.5, 0),\n\t\tPosition = UDim2.fromScale(0.5, y),\n\t\tSize = UDim2.fromScale(0.5, 0.17),\n\t\tBackgroundColor3 = Theme.white,\n\t\tTextColor3 = Theme.text,\n\t\tPlaceholderText = placeholder,\n\t\tPlaceholderColor3 = Theme.muted,\n\t\tText = \"\",\n\t\tFontFace = Theme.bold,\n\t\tTextScaled = true,\n\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\tClearTextOnFocus = false,\n\t\tParent = overlayBody,\n\t}, { Ui.corner(6), Ui.pad(10, 6), Ui.maxText(24) })\nend\n\n-- Once paid for, the drawer can type any word. The server checks it's allowed.\nlocal function renderCustomForm()\n\tlocal word = textField(\"Type any word to draw\", 0.06)\n\n\tlocal errorLabel = label({\n\t\tPosition = UDim2.fromScale(0, 0.3),\n\t\tSize = UDim2.fromScale(1, 0.12),\n\t\tText = \"\",\n\t\tTextColor3 = Theme.yellow,\n\t\tParent = overlayBody,\n\t}, { Ui.maxText(22) })\n\tcustomError = errorLabel\n\n\tlocal use = Ui.overlayButton({\n\t\tText = \"Use word\",\n\t\tAnchorPoint = Vector2.new(0.5, 0),\n\t\tPosition = UDim2.fromScale(0.5, 0.48),\n\t\tSize = UDim2.fromScale(0.3, 0.2),\n\t\tParent = overlayBody,\n\t})\n\tlocal back = Ui.overlayButton({\n\t\tText = \"Back\",\n\t\tPosition = UDim2.fromScale(0, 0.52),\n\t\tSize = UDim2.fromScale(0.16, 0.14),\n\t\tParent = overlayBody,\n\t})\n\n\tlocal function submit()\n\t\tif string.match(word.Text, \"%a\") == nil then\n\t\t\terrorLabel.Text = \"Type a word first.\"\n\t\t\treturn\n\t\tend\n\t\terrorLabel.Text = \"Checking...\"\n\t\tWordChoiceEvent:FireServer({ word = word.Text })\n\tend\n\tuse.Activated:Connect(submit)\n\tword.FocusLost:Connect(function(enterPressed)\n\t\tif enterPressed then\n\t\t\tsubmit()\n\t\tend\n\tend)\n\tback.Activated:Connect(function()\n\t\tcustomForm = false\n\t\trender()\n\tend)\n\ttask.defer(function()\n\t\tword:CaptureFocus()\n\tend)\nend\n\nlocal function renderTurnResults(lastTurn)\n\tlocal list = make(\"Frame\", {\n\t\tPosition = UDim2.fromScale(0.2, 0),\n\t\tSize = UDim2.fromScale(0.6, 1),\n\t\tBackgroundTransparency = 1,\n\t\tParent = overlayBody,\n\t}, {\n\t\tmake(\"UIListLayout\", {\n\t\t\tPadding = UDim.new(0.02, 0),\n\t\t\tHorizontalAlignment = Enum.HorizontalAlignment.Center,\n\t\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t\t}),\n\t})\n\n\tif #lastTurn.results == 0 then\n\t\tlocal nobody = title({ Size = UDim2.fromScale(1, 0.14), Text = \"Nobody guessed it!\", TextColor3 = Theme.overlayText, Parent = list }, { Ui.maxText(26) })\n\t\tpopLater(nobody, 0.3)\n\t\treturn\n\tend\n\tfor i, result in lastTurn.results do\n\t\tif i > 7 then\n\t\t\tbreak\n\t\tend\n\t\tlocal resultRow = make(\"Frame\", {\n\t\t\tSize = UDim2.fromScale(1, 0.12),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tLayoutOrder = i,\n\t\t\tParent = list,\n\t\t})\n\t\ttitle({\n\t\t\tSize = UDim2.fromScale(0.7, 1),\n\t\t\tText = result.name .. (if result.isDrawer then \" \226\156\143\239\184\143\" else \"\"),\n\t\t\tTextXAlignment = Enum.TextXAlignment.Left,\n\t\t\tParent = resultRow,\n\t\t}, { Ui.maxText(24) })\n\t\ttitle({\n\t\t\tAnchorPoint = Vector2.new(1, 0),\n\t\t\tPosition = UDim2.fromScale(1, 0),\n\t\t\tSize = UDim2.fromScale(0.3, 1),\n\t\t\tText = `+{result.points}`,\n\t\t\tTextColor3 = Theme.yellow,\n\t\t\tTextXAlignment = Enum.TextXAlignment.Right,\n\t\t\tParent = resultRow,\n\t\t}, { Ui.maxText(24) })\n\t\tpopLater(resultRow, 0.2 + i * 0.08)\n\tend\nend\n\nlocal PODIUM = {\n\t{ place = 2, height = 0.42, color = Theme.silver, delay = 0.4 },\n\t{ place = 1, height = 0.58, color = Theme.gold, delay = 0.8 },\n\t{ place = 3, height = 0.3, color = Theme.bronze, delay = 0 },\n}\n\nlocal function renderPodium(winners)\n\tlocal row = make(\"Frame\", {\n\t\tPosition = UDim2.fromScale(0.1, 0),\n\t\tSize = UDim2.fromScale(0.8, 1),\n\t\tBackgroundTransparency = 1,\n\t\tParent = overlayBody,\n\t}, {\n\t\tmake(\"UIListLayout\", {\n\t\t\tFillDirection = Enum.FillDirection.Horizontal,\n\t\t\tHorizontalAlignment = Enum.HorizontalAlignment.Center,\n\t\t\tVerticalAlignment = Enum.VerticalAlignment.Bottom,\n\t\t\tPadding = UDim.new(0.03, 0),\n\t\t\tSortOrder = Enum.SortOrder.LayoutOrder,\n\t\t}),\n\t})\n\tfor order, slot in PODIUM do\n\t\tlocal names, score, userId = {}, 0, nil\n\t\tfor _, winner in winners do\n\t\t\tif winner.place == slot.place then\n\t\t\t\ttable.insert(names, winner.name)\n\t\t\t\tscore = winner.score\n\t\t\t\tuserId = userId or winner.userId\n\t\t\tend\n\t\tend\n\t\tlocal column = make(\"Frame\", {\n\t\t\tSize = UDim2.fromScale(0.3, 1),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tLayoutOrder = order,\n\t\t\tParent = row,\n\t\t})\n\t\tif #names > 0 then\n\t\t\t-- The block grows up from the floor, carrying the winner's avatar and name on top.\n\t\t\tlocal block = make(\"Frame\", {\n\t\t\t\tAnchorPoint = Vector2.new(0, 1),\n\t\t\t\tPosition = UDim2.fromScale(0, 1),\n\t\t\t\tSize = UDim2.fromScale(1, 0),\n\t\t\t\tBackgroundColor3 = slot.color,\n\t\t\t\tParent = column,\n\t\t\t}, { Ui.corner(6) })\n\t\t\ttitle({\n\t\t\t\tSize = UDim2.fromScale(1, 0.6),\n\t\t\t\tText = `#{slot.place}`,\n\t\t\t\tTextColor3 = Theme.outline,\n\t\t\t\tParent = block,\n\t\t\t}, { Ui.maxText(40), Ui.pad(6) })\n\t\t\tlabel({\n\t\t\t\tPosition = UDim2.fromScale(0, 0.55),\n\t\t\t\tSize = UDim2.fromScale(1, 0.3),\n\t\t\t\tText = `{score} points`,\n\t\t\t\tTextColor3 = Theme.outline,\n\t\t\t\tParent = block,\n\t\t\t}, { Ui.maxText(20), Ui.pad(4) })\n\n\t\t\tlocal plate = make(\"Frame\", {\n\t\t\t\tAnchorPoint = Vector2.new(0.5, 1),\n\t\t\t\tPosition = UDim2.new(0.5, 0, 1, -4),\n\t\t\t\tSize = UDim2.fromScale(1, 0.4),\n\t\t\t\tBackgroundTransparency = 1,\n\t\t\t\tParent = column,\n\t\t\t})\n\t\t\tlocal avatar = Ui.avatar(userId, names[1], {\n\t\t\t\tAnchorPoint = Vector2.new(0.5, 0),\n\t\t\t\tPosition = UDim2.fromScale(0.5, 0.1),\n\t\t\t\tSize = UDim2.fromScale(0.62, 0.6),\n\t\t\t\tParent = plate,\n\t\t\t})\n\t\t\tUi.square().Parent = avatar\n\t\t\ttitle({\n\t\t\t\tPosition = UDim2.fromScale(0, 0.72),\n\t\t\t\tSize = UDim2.fromScale(1, 0.26),\n\t\t\t\tText = (if slot.place == 1 then \"\240\159\145\145 \" else \"\") .. table.concat(names, \" & \"),\n\t\t\t\tParent = plate,\n\t\t\t}, { Ui.maxText(22) })\n\n\t\t\ttask.delay(slot.delay, function()\n\t\t\t\tUi.tween(block, 0.6, { Size = UDim2.fromScale(1, slot.height) }, Enum.EasingStyle.Back)\n\t\t\t\tUi.tween(plate, 0.6, { Position = UDim2.new(0.5, 0, 1 - slot.height, -4) }, Enum.EasingStyle.Back)\n\t\t\t\tif slot.place == 1 then\n\t\t\t\t\ttask.delay(0.6, function()\n\t\t\t\t\t\tUi.pulse(avatar, 1.3)\n\t\t\t\t\tend)\n\t\t\t\tend\n\t\t\tend)\n\t\tend\n\tend\nend\n\n-- Once Roblox tells us the real prices, redraw the price labels.\ntable.insert(priceListeners, function()\n\tif snapshot then\n\t\trender()\n\tend\nend)\n\nlocal overlayKey: string? = nil\nlocal overlayPhase: string? = nil\nlocal overlayShown = true\n\nlocal function setOverlayShown(show: boolean)\n\tif show == overlayShown then\n\t\treturn\n\tend\n\toverlayShown = show\n\tif show then\n\t\toverlay.Visible = true\n\t\toverlay.BackgroundTransparency = 1\n\t\tUi.tween(overlay, 0.25, { BackgroundTransparency = Theme.overlayTransparency })\n\telse\n\t\tUi.tween(overlay, 0.25, { BackgroundTransparency = 1 })\n\t\tUi.tween(overlayContent, 0.25, { Position = UDim2.fromScale(0, -1) }, Enum.EasingStyle.Back, Enum.EasingDirection.In).Completed:Connect(\n\t\t\tfunction()\n\t\t\t\tif not overlayShown then\n\t\t\t\t\toverlay.Visible = false\n\t\t\t\tend\n\t\t\tend\n\t\t)\n\tend\nend\n\nlocal function buildOverlay(s)\n\tlocal key = if s.phase == \"Waiting\"\n\t\tthen `Waiting{#s.players}`\n\t\telseif s.phase == \"Choosing\" then `Choosing{s.drawerUserId}{if wordChoices then \"pick\" else \"\"}{if customForm then \"custom\" else \"\"}{chosenWord or \"\"}`\n\t\telse `{s.phase}{s.phaseEndsAt}`\n\tif key == overlayKey then\n\t\treturn\n\tend\n\toverlayKey = key\n\tlocal newPhase = s.phase ~= overlayPhase\n\toverlayPhase = s.phase\n\n\tsetOverlayShown(s.phase ~= \"Drawing\")\n\tif s.phase == \"Drawing\" then\n\t\treturn\n\tend\n\n\tclearChildren(overlayBody)\n\tcountdownLabel = nil\n\tif s.phase == \"Waiting\" then\n\t\toverlayHeader(\"Waiting for players...\", `{#s.players}/{s.minPlayers} players - invite a friend!`)\n\t\twobblingEmoji(\"\226\156\143\239\184\143\")\n\telseif s.phase == \"Starting\" then\n\t\toverlayHeader(\"Get ready!\", `{s.totalRounds} rounds - everyone draws once per round`)\n\t\tcountdownLabel = title({\n\t\t\tSize = UDim2.fromScale(1, 0.8),\n\t\t\tText = \"\",\n\t\t\tTextColor3 = Theme.yellow,\n\t\t\tParent = overlayBody,\n\t\t}, { Ui.maxText(140) })\n\telseif s.phase == \"Choosing\" then\n\t\tif s.isDrawer and wordChoices and customForm then\n\t\t\toverlayHeader(\"Custom word\", \"Draw anything you like - keep it family friendly!\")\n\t\t\trenderCustomForm()\n\t\telseif s.isDrawer and wordChoices then\n\t\t\toverlayHeader(\"Choose a word\", \"\")\n\t\t\trenderWordChoices()\n\t\telseif s.isDrawer then\n\t\t\toverlayHeader(\"Get ready to draw!\", chosenWord or \"\")\n\t\t\twobblingEmoji(\"\226\156\143\239\184\143\")\n\t\telse\n\t\t\toverlayHeader(`{s.drawerName} is choosing a word!`, \"\")\n\t\t\tlocal avatar = Ui.avatar(s.drawerUserId, s.drawerName, {\n\t\t\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\t\t\tPosition = UDim2.fromScale(0.5, 0.3),\n\t\t\t\tSize = UDim2.fromScale(0.4, 0.55),\n\t\t\t\tRotation = -6,\n\t\t\t\tParent = overlayBody,\n\t\t\t})\n\t\t\tUi.square().Parent = avatar\n\t\t\tUi.loop(avatar, 0.8, { Rotation = 6 })\n\t\tend\n\telseif s.phase == \"TurnEnd\" and s.lastTurn then\n\t\toverlayTitle.RichText = true\n\t\toverlayHeader(`The word was {colorTag(Theme.yellow, `'{escapeRichText(s.lastTurn.word or \"\")}'`)}`, s.lastTurn.reason)\n\t\trenderTurnResults(s.lastTurn)\n\telseif s.phase == \"MatchEnd\" and s.winners then\n\t\toverlayHeader(\"Results\", \"\")\n\t\trenderPodium(s.winners)\n\tend\n\tif s.phase ~= \"TurnEnd\" then\n\t\toverlayTitle.RichText = false\n\tend\n\n\tif newPhase then\n\t\toverlayContent.Position = UDim2.fromScale(0, -0.6)\n\t\tUi.tween(overlayContent, 0.45, { Position = UDim2.new() }, Enum.EasingStyle.Back)\n\telse\n\t\toverlayContent.Position = UDim2.new()\n\tend\nend\n\n-- Rendering the game state --------------------------------------------------------------------------\n\nlocal TIMED_PHASES = { Starting = true, Choosing = true, Drawing = true, TurnEnd = true, MatchEnd = true }\nlocal toolbarShown = false\n\nfunction render()\n\tlocal s = snapshot\n\tif not s then\n\t\treturn\n\tend\n\n\troundLabel.Text = if s.round > 0 then `Round {s.round} of {s.totalRounds}` else \"Waiting\"\n\t-- This turn's word theme: shown in the top bar and on everyone's background.\n\tlocal theme = Themes.byId[s.theme] or Themes.byId.general\n\tthemeLabel.Text = `{theme.emoji} {theme.name} words`\n\tapplyTheme(theme.id)\n\tif s.myTheme and s.myTheme ~= myTheme then\n\t\tmyTheme = s.myTheme\n\t\tshowMyTheme()\n\tend\n\tif s.word and s.isDrawer then\n\t\twordCaption.Text = \"DRAW THIS\"\n\t\tsetWord(s.word, false, Theme.text)\n\telseif s.word and s.wordIsFull then\n\t\twordCaption.Text = if s.phase == \"TurnEnd\" then \"THE WORD WAS\" else \"YOU GOT IT!\"\n\t\tsetWord(s.word, false, Theme.green)\n\telseif s.word then\n\t\twordCaption.Text = \"GUESS THIS\"\n\t\tsetWord(s.word, true, Theme.text)\n\telse\n\t\twordCaption.Text = \"WAITING\"\n\t\tsetWord(nil, false, Theme.text)\n\tend\n\n\trenderPlayers(s.players)\n\n\tlocal canShop = s.phase == \"Drawing\" and not s.isDrawer\n\tif canShop ~= shopBar.Visible then\n\t\tshopBar.Visible = canShop\n\t\tif canShop then\n\t\t\tUi.pop(shopBar, 0.8, 0.3)\n\t\tend\n\tend\n\tfor item, priceLabel in shopPriceLabels do\n\t\tlocal owned = s.credits and s.credits[item] or 0\n\t\tpriceLabel.Text = if owned > 0 then `Use ({owned})` else `{ROBUX}{priceOf(item)}`\n\tend\n\n\t-- \"Vote Kick: 1/3\" votes against whoever is drawing; greyed out when it can't be used.\n\tlocal canVoteKick = s.drawerUserId ~= nil and not s.isDrawer and not s.votedOnDrawer\n\tvoteKickButton.Text = `Vote Kick: {s.drawerKickVotes or 0}/{s.kickVotesNeeded or 2}`\n\tvoteKickButton.BackgroundColor3 = if canVoteKick then Color3.fromRGB(255, 150, 30) else Color3.fromRGB(200, 190, 175)\n\n\tlocal canRate = s.phase == \"Drawing\" and not s.isDrawer and not ratedThisTurn\n\tif canRate ~= rateBar.Visible then\n\t\trateBar.Visible = canRate\n\t\tif canRate then\n\t\t\tUi.pop(rateBar, 0.7, 0.3)\n\t\tend\n\tend\n\tif kickTarget and not rows[kickTarget] then\n\t\tcloseKickMenu() -- they left\n\tend\n\n\tif s.canDraw ~= toolbarShown then\n\t\ttoolbarShown = s.canDraw\n\t\ttoolbar.Visible = s.canDraw\n\t\tif s.canDraw then\n\t\t\tUi.pop(toolbar, 0.7, 0.3)\n\t\tend\n\tend\n\tif not s.canDraw then\n\t\tpicker:close()\n\t\tif activeStroke then\n\t\t\tendStroke()\n\t\tend\n\tend\n\tguessBox.PlaceholderText = if s.phase == \"Drawing\" and (s.isDrawer or s.wordIsFull)\n\t\tthen \"Chat (only players who guessed see this)\"\n\t\telse \"Type your guess here...\"\n\n\tbuildOverlay(s)\nend\n\nlocal function countHidden(word: string?): number\n\tlocal _, count = string.gsub(word or \"\", \"_\", \"\")\n\treturn count\nend\n\n-- Sounds and effects for whatever changed between two snapshots.\nlocal function celebrate(old, new)\n\tif not old then\n\t\treturn\n\tend\n\n\tlocal sameTurn = old.phase == new.phase and old.drawerUserId == new.drawerUserId\n\tif new.phase ~= old.phase then\n\t\tif new.phase == \"Drawing\" then\n\t\t\tSounds.play(\"click\")\n\t\t\tEffects.floatText(if new.isDrawer then \"Draw!\" else \"Guess!\", Theme.yellow, Effects.centreOf(canvas), 72)\n\t\telseif new.phase == \"TurnEnd\" then\n\t\t\tSounds.play(if new.lastTurn and new.lastTurn.everyoneGuessed then \"correct\" else \"timeUp\")\n\t\telseif new.phase == \"MatchEnd\" then\n\t\t\tSounds.play(\"victory\")\n\t\t\tEffects.confetti(110)\n\t\t\ttask.delay(0.8, Effects.confetti, 70)\n\t\telseif new.phase == \"Starting\" then\n\t\t\tSounds.play(\"yourTurn\", 0.6)\n\t\tend\n\tend\n\n\t-- A hint letter appeared.\n\tif sameTurn and new.phase == \"Drawing\" and not new.wordIsFull and countHidden(new.word) < countHidden(old.word) then\n\t\tUi.pulse(wordRow, 1.3)\n\t\tSounds.play(\"click\")\n\tend\n\n\tlocal before = {}\n\tfor _, entry in old.players do\n\t\tbefore[entry.userId] = entry\n\tend\n\tfor _, entry in new.players do\n\t\tlocal previous = before[entry.userId]\n\t\tlocal row = rows[entry.userId]\n\t\tif previous and row then\n\t\t\tlocal gained = entry.score - previous.score\n\t\t\tif gained > 0 then\n\t\t\t\tUi.pulse(row.frame, 1.05)\n\t\t\t\tEffects.floatText(`+{gained}`, Theme.green, Effects.centreOf(row.frame), 28)\n\t\t\tend\n\t\t\tif entry.guessed and not previous.guessed then\n\t\t\t\tif entry.userId == player.UserId then\n\t\t\t\t\tSounds.play(\"correct\")\n\t\t\t\t\tUi.pulse(wordArea, 1.2)\n\t\t\t\t\tEffects.floatText(`Nice! +{gained}`, Theme.green, Effects.centreOf(canvas), 56)\n\t\t\t\telse\n\t\t\t\t\tSounds.play(\"correct\", 0.4)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend\n\nStateEvent.OnClientEvent:Connect(function(newSnapshot)\n\tlocal previous = snapshot\n\tsnapshot = newSnapshot\n\tif newSnapshot.phase ~= \"Choosing\" then\n\t\twordChoices = nil\n\t\tchosenWord = nil\n\t\tcustomForm = false\n\tend\n\tif newSnapshot.phase ~= \"Drawing\" then\n\t\tratedThisTurn = false\n\tend\n\trender()\n\t-- Wait a frame so freshly reordered rows have their final positions.\n\ttask.defer(celebrate, previous, newSnapshot)\nend)\n\nWordChoiceEvent.OnClientEvent:Connect(function(options)\n\t-- A custom word was paid for (or unlocked): show the form.\n\tif typeof(options) == \"table\" and options.custom then\n\t\tcustomForm = true\n\t\tSounds.play(\"yourTurn\", 0.6)\n\t\trender()\n\t\treturn\n\tend\n\t-- The server turned down a custom word.\n\tif typeof(options) == \"table\" and options.error then\n\t\tlocal errorLabel = customError\n\t\tif errorLabel and errorLabel.Parent then\n\t\t\terrorLabel.Text = options.error\n\t\t\tUi.shake(errorLabel, 4)\n\t\tend\n\t\tSounds.play(\"tick\")\n\t\treturn\n\tend\n\twordChoices = options\n\tif options then\n\t\tSounds.play(\"yourTurn\")\n\tend\n\trender()\nend)\n\n-- Someone bought a nuke: a flash, a shake and a big boom over the canvas.\nShopEvent.OnClientEvent:Connect(function(effect)\n\tif effect ~= \"nuke\" then\n\t\treturn\n\tend\n\tlocal flash = canvasLayer(\"Frame\", {\n\t\tBackgroundColor3 = Color3.fromRGB(255, 230, 150),\n\t\tBackgroundTransparency = 0,\n\t\tZIndex = 6,\n\t}, { Ui.corner(4) })\n\tUi.tween(flash, 0.8, { BackgroundTransparency = 1 })\n\ttask.delay(0.9, function()\n\t\tflash:Destroy()\n\tend)\n\tUi.shake(canvasArea, 4)\n\tEffects.floatText(\"\240\159\146\165\", Theme.white, Effects.centreOf(canvas), 140)\n\tSounds.play(\"timeUp\", 0.7)\nend)\n\n-- Timer ------------------------------------------------------------------------------------------------\n\nlocal lastSecond: number? = nil\n\nRunService.RenderStepped:Connect(function()\n\tlocal s = snapshot\n\tif not (s and TIMED_PHASES[s.phase]) then\n\t\ttimerLabel.Text = \"\"\n\t\tlastSecond = nil\n\t\treturn\n\tend\n\tlocal remaining = math.max(0, math.ceil(s.phaseEndsAt - workspace:GetServerTimeNow()))\n\tif remaining == lastSecond then\n\t\treturn\n\tend\n\tlastSecond = remaining\n\ttimerLabel.Text = tostring(remaining)\n\n\tlocal hurry = s.phase == \"Drawing\" and remaining <= 10 and remaining > 0\n\ttimerLabel.TextColor3 = if hurry then Theme.red else Theme.text\n\tif hurry then\n\t\tSounds.play(\"tick\")\n\t\tUi.pulse(clock, 1.15)\n\t\tUi.shake(clock, 12)\n\tend\n\n\tlocal countdown = countdownLabel\n\tif s.phase == \"Starting\" and countdown and remaining > 0 then\n\t\tcountdown.Text = tostring(remaining)\n\t\tUi.pop(countdown, 1.8, 0.3)\n\t\tSounds.play(\"tick\")\n\tend\nend)\n\n-- Entrance -----------------------------------------------------------------------------------------------\n\nlocal function slideIn(gui: GuiObject, from: UDim2, delay: number)\n\tlocal target = gui.Position\n\tgui.Position = target + from\n\ttask.delay(delay, function()\n\t\tUi.tween(gui, 0.6, { Position = target }, Enum.EasingStyle.Back)\n\tend)\nend\n\nslideIn(logo, UDim2.fromScale(0, -0.15), 0)\nslideIn(topBar, UDim2.fromScale(0, -0.25), 0.05)\nslideIn(playersScroller, UDim2.fromScale(-0.25, 0), 0.12)\nslideIn(chatPanel, UDim2.fromScale(0.3, 0), 0.18)\npopLater(canvasArea, 0.25, 0.6)\n\n-- Everything is wired up; ask the server for the current state and drawing.\nCanvasEvent:FireServer(\"ready\")\n"); put(client,"CanvasRenderer","ModuleScript","-- Draws the shared canvas. Points are normalised: x and y both run 0..1 across it.\n--\n-- Strokes are rotated, rounded Frames. Alongside them a low-resolution grid\n-- records which colour covers each spot, so the bucket can flood-fill. Every\n-- client builds the same grid from the same history, so a fill comes out the\n-- same on every screen. Fills are drawn underneath the strokes, slightly\n-- oversized, so they tuck neatly under the lines around them.\n\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Config = require(ReplicatedStorage:WaitForChild(\"GuessAndDraw\"):WaitForChild(\"Config\"))\n\n-- Canvas height measured in canvas widths, so lengths are the same in both axes.\nlocal HEIGHT_IN_WIDTHS = 1 / Config.CANVAS_ASPECT\n\nlocal GRID_W = Config.FILL_GRID_WIDTH\nlocal GRID_H = math.floor(GRID_W * HEIGHT_IN_WIDTHS + 0.5) -- square cells\nlocal CELLS = GRID_W * GRID_H\nlocal MIN_STAMP_RADIUS = 0.75 -- cells; keeps the thinnest lines solid walls for the fill\nlocal FILL_OVERLAP = 0.6 -- cells each fill rectangle reaches under its neighbours\n\nlocal CanvasRenderer = {}\nCanvasRenderer.__index = CanvasRenderer\n\n-- Colours travel as 0xRRGGBB numbers.\nfunction CanvasRenderer.toInt(color: Color3): number\n\treturn math.floor(color.R * 255 + 0.5) * 65536 + math.floor(color.G * 255 + 0.5) * 256 + math.floor(color.B * 255 + 0.5)\nend\n\nfunction CanvasRenderer.toColor(value: number): Color3\n\treturn Color3.fromRGB(value // 65536 % 256, value // 256 % 256, value % 256)\nend\n\nlocal BACKGROUND = CanvasRenderer.toInt(Config.BACKGROUND_COLOR)\n\ntype Segment = { frame: Frame, cell: number, colorInt: number }\n\ntype Item = {\n\tkind: string, -- \"stroke\" or \"fill\"\n\tid: number,\n\tcolorInt: number,\n\tcontainer: Frame?,\n\t-- strokes\n\tthickness: number?,\n\tpoints: { number }?,\n\tsegments: { Segment }?,\n\tlastX: number?,\n\tlastY: number?,\n\t-- fills\n\tx: number?,\n\ty: number?,\n\trecolored: { { segment: Segment, previous: number } }?,\n}\n\nexport type Renderer = typeof(setmetatable(\n\t{} :: {\n\t\tcanvas: GuiObject,\n\t\tfillLayer: Frame,\n\t\titems: { Item },\n\t\tbyId: { [number]: Item },\n\t\tlayer: number,\n\t\tfillLayerZ: number,\n\t\tgrid: buffer,\n\t},\n\tCanvasRenderer\n))\n\nlocal function resetGrid(grid: buffer)\n\tfor i = 0, CELLS - 1 do\n\t\tbuffer.writeu32(grid, i * 4, BACKGROUND)\n\tend\nend\n\nlocal function cellAt(x: number, y: number): number\n\tlocal cx = math.clamp(math.floor(x * GRID_W), 0, GRID_W - 1)\n\tlocal cy = math.clamp(math.floor(y * GRID_H), 0, GRID_H - 1)\n\treturn cy * GRID_W + cx\nend\n\n-- Paints a round-ended line of the given diameter (in canvas widths) into the grid.\nlocal function stamp(grid: buffer, x1: number, y1: number, x2: number, y2: number, thickness: number, colorInt: number)\n\tlocal ax, ay = x1 * GRID_W, y1 * GRID_H\n\tlocal bx, by = x2 * GRID_W, y2 * GRID_H\n\tlocal radius = math.max(thickness * GRID_W / 2, MIN_STAMP_RADIUS)\n\tlocal radiusSq = radius * radius\n\tlocal dx, dy = bx - ax, by - ay\n\tlocal lengthSq = dx * dx + dy * dy\n\n\tlocal minX = math.max(0, math.floor(math.min(ax, bx) - radius))\n\tlocal maxX = math.min(GRID_W - 1, math.ceil(math.max(ax, bx) + radius))\n\tlocal minY = math.max(0, math.floor(math.min(ay, by) - radius))\n\tlocal maxY = math.min(GRID_H - 1, math.ceil(math.max(ay, by) + radius))\n\tfor cy = minY, maxY do\n\t\tlocal py = cy + 0.5\n\t\tfor cx = minX, maxX do\n\t\t\tlocal px = cx + 0.5\n\t\t\tlocal t = 0\n\t\t\tif lengthSq > 0 then\n\t\t\t\tt = math.clamp(((px - ax) * dx + (py - ay) * dy) / lengthSq, 0, 1)\n\t\t\tend\n\t\t\tlocal qx, qy = ax + t * dx - px, ay + t * dy - py\n\t\t\tif qx * qx + qy * qy <= radiusSq then\n\t\t\t\tbuffer.writeu32(grid, (cy * GRID_W + cx) * 4, colorInt)\n\t\t\tend\n\t\tend\n\tend\nend\n\n-- Floods the area of matching colour around (x, y) with `colorInt`. Returns the\n-- colour that was replaced and a mask of the flooded cells, or nil if the spot\n-- already had that colour.\nlocal function flood(grid: buffer, x: number, y: number, colorInt: number): (number, buffer?)\n\tlocal start = cellAt(x, y)\n\tlocal old = buffer.readu32(grid, start * 4)\n\tif old == colorInt then\n\t\treturn old, nil\n\tend\n\tlocal mask = buffer.create(CELLS)\n\tlocal stack = table.create(1024)\n\tlocal top = 1\n\tstack[1] = start\n\tbuffer.writeu32(grid, start * 4, colorInt)\n\tbuffer.writeu8(mask, start, 1)\n\twhile top > 0 do\n\t\tlocal i = stack[top]\n\t\ttop -= 1\n\t\tlocal column = i % GRID_W\n\t\t-- Left, right, up, down.\n\t\tfor _, n in { if column > 0 then i - 1 else -1, if column < GRID_W - 1 then i + 1 else -1, i - GRID_W, i + GRID_W } do\n\t\t\tif n >= 0 and n < CELLS and buffer.readu32(grid, n * 4) == old then\n\t\t\t\tbuffer.writeu32(grid, n * 4, colorInt)\n\t\t\t\tbuffer.writeu8(mask, n, 1)\n\t\t\t\ttop += 1\n\t\t\t\tstack[top] = n\n\t\t\tend\n\t\tend\n\tend\n\treturn old, mask\nend\n\n-- Draws the flooded cells as rectangles: runs along each row, with identical runs\n-- in consecutive rows merged into one taller rectangle.\nlocal function drawMask(container: Frame, mask: buffer, color: Color3)\n\tlocal function emit(x0: number, x1: number, y0: number, y1: number)\n\t\tlocal frame = Instance.new(\"Frame\")\n\t\tframe.BorderSizePixel = 0\n\t\tframe.BackgroundColor3 = color\n\t\tframe.Position = UDim2.fromScale((x0 - FILL_OVERLAP) / GRID_W, (y0 - FILL_OVERLAP) / GRID_H)\n\t\tframe.Size = UDim2.fromScale((x1 - x0 + 1 + 2 * FILL_OVERLAP) / GRID_W, (y1 - y0 + 1 + 2 * FILL_OVERLAP) / GRID_H)\n\t\tframe.Parent = container\n\tend\n\n\tlocal open: { [number]: number } = {} -- run key (x0 * GRID_W + x1) -> first row\n\tfor y = 0, GRID_H - 1 do\n\t\tlocal row: { [number]: boolean } = {}\n\t\tlocal x = 0\n\t\twhile x < GRID_W do\n\t\t\tif buffer.readu8(mask, y * GRID_W + x) == 1 then\n\t\t\t\tlocal x0 = x\n\t\t\t\twhile x < GRID_W and buffer.readu8(mask, y * GRID_W + x) == 1 do\n\t\t\t\t\tx += 1\n\t\t\t\tend\n\t\t\t\trow[x0 * GRID_W + x - 1] = true\n\t\t\telse\n\t\t\t\tx += 1\n\t\t\tend\n\t\tend\n\t\tfor key, firstRow in open do\n\t\t\tif not row[key] then\n\t\t\t\temit(key // GRID_W, key % GRID_W, firstRow, y - 1)\n\t\t\t\topen[key] = nil\n\t\t\tend\n\t\tend\n\t\tfor key in row do\n\t\t\tif not open[key] then\n\t\t\t\topen[key] = y\n\t\t\tend\n\t\tend\n\tend\n\tfor key, firstRow in open do\n\t\temit(key // GRID_W, key % GRID_W, firstRow, GRID_H - 1)\n\tend\nend\n\nfunction CanvasRenderer.new(canvas: GuiObject): Renderer\n\t-- All fills live in one layer under every stroke.\n\tlocal fillLayer = Instance.new(\"Frame\")\n\tfillLayer.Name = \"Fills\"\n\tfillLayer.BackgroundTransparency = 1\n\tfillLayer.Size = UDim2.fromScale(1, 1)\n\tfillLayer.ZIndex = 0\n\tfillLayer.Parent = canvas\n\n\tlocal grid = buffer.create(CELLS * 4)\n\tresetGrid(grid)\n\treturn setmetatable({\n\t\tcanvas = canvas,\n\t\tfillLayer = fillLayer,\n\t\titems = {},\n\t\tbyId = {},\n\t\tlayer = 0,\n\t\tfillLayerZ = 0,\n\t\tgrid = grid,\n\t}, CanvasRenderer)\nend\n\nlocal function drawSegment(stroke: Item, grid: buffer, x1: number, y1: number, x2: number, y2: number)\n\tlocal thickness = stroke.thickness :: number\n\tlocal dx = x2 - x1\n\tlocal dy = (y2 - y1) * HEIGHT_IN_WIDTHS\n\tlocal length = math.sqrt(dx * dx + dy * dy)\n\n\tlocal frame = Instance.new(\"Frame\")\n\tframe.BorderSizePixel = 0\n\tframe.BackgroundColor3 = CanvasRenderer.toColor(stroke.colorInt)\n\tframe.AnchorPoint = Vector2.new(0.5, 0.5)\n\tframe.Position = UDim2.fromScale((x1 + x2) / 2, (y1 + y2) / 2)\n\t-- Width covers the segment plus a round cap at each end; height is the brush diameter.\n\tframe.Size = UDim2.fromScale(length + thickness, thickness / HEIGHT_IN_WIDTHS)\n\tframe.Rotation = math.deg(math.atan2(dy, dx))\n\n\tlocal corner = Instance.new(\"UICorner\")\n\tcorner.CornerRadius = UDim.new(0.5, 0)\n\tcorner.Parent = frame\n\n\tframe.Parent = stroke.container\n\ttable.insert(stroke.segments :: { Segment }, {\n\t\tframe = frame,\n\t\tcell = cellAt((x1 + x2) / 2, (y1 + y2) / 2),\n\t\tcolorInt = stroke.colorInt,\n\t})\n\tstamp(grid, x1, y1, x2, y2, thickness, stroke.colorInt)\nend\n\n-- Adds points to a stroke, creating it if needed. `points` is a flat {x1, y1, x2, y2, ...}.\nfunction CanvasRenderer.addPoints(self: Renderer, id: number, colorInt: number, sizeIndex: number, points: { number })\n\tlocal stroke = self.byId[id]\n\tif stroke and stroke.kind ~= \"stroke\" then\n\t\treturn\n\tend\n\tif not stroke then\n\t\tself.layer += 1\n\t\tlocal container = Instance.new(\"Frame\")\n\t\tcontainer.Name = tostring(id)\n\t\tcontainer.BackgroundTransparency = 1\n\t\tcontainer.Size = UDim2.fromScale(1, 1)\n\t\tcontainer.ZIndex = self.layer -- later strokes paint over earlier ones\n\t\tcontainer.Parent = self.canvas\n\t\tstroke = {\n\t\t\tkind = \"stroke\",\n\t\t\tid = id,\n\t\t\tcolorInt = colorInt,\n\t\t\tcontainer = container,\n\t\t\tthickness = Config.BRUSH_SIZES[sizeIndex] or Config.BRUSH_SIZES[1],\n\t\t\tpoints = {},\n\t\t\tsegments = {},\n\t\t}\n\t\tself.byId[id] = stroke\n\t\ttable.insert(self.items, stroke)\n\tend\n\n\tlocal item = stroke :: Item\n\tfor i = 1, #points - 1, 2 do\n\t\tlocal x, y = points[i], points[i + 1]\n\t\ttable.insert(item.points :: { number }, x)\n\t\ttable.insert(item.points :: { number }, y)\n\t\tif item.lastX then\n\t\t\tif x ~= item.lastX or y ~= item.lastY then\n\t\t\t\tdrawSegment(item, self.grid, item.lastX :: number, item.lastY :: number, x, y)\n\t\t\tend\n\t\telse\n\t\t\tdrawSegment(item, self.grid, x, y, x, y) -- a dot\n\t\tend\n\t\titem.lastX, item.lastY = x, y\n\tend\nend\n\n-- Bucket fill at (x, y).\nfunction CanvasRenderer.fill(self: Renderer, id: number, colorInt: number, x: number, y: number)\n\tif self.byId[id] then\n\t\treturn\n\tend\n\tlocal item: Item = { kind = \"fill\", id = id, colorInt = colorInt, x = x, y = y, recolored = {} }\n\tself.byId[id] = item\n\ttable.insert(self.items, item)\n\n\tlocal old, mask = flood(self.grid, x, y, colorInt)\n\tif not mask then\n\t\treturn\n\tend\n\tlocal color = CanvasRenderer.toColor(colorInt)\n\tself.fillLayerZ += 1\n\tlocal container = Instance.new(\"Frame\")\n\tcontainer.Name = `Fill{id}`\n\tcontainer.BackgroundTransparency = 1\n\tcontainer.Size = UDim2.fromScale(1, 1)\n\tcontainer.ZIndex = self.fillLayerZ\n\tcontainer.Parent = self.fillLayer\n\titem.container = container\n\tdrawMask(container, mask, color)\n\n\t-- Strokes sit above fills, so any stroke pieces that were part of the flooded\n\t-- colour (e.g. eraser marks on a white background) take the new colour too.\n\tlocal recolored = item.recolored :: { any }\n\tfor _, other in self.items do\n\t\tif other.kind == \"stroke\" then\n\t\t\tfor _, segment in other.segments :: { Segment } do\n\t\t\t\tif segment.colorInt == old and buffer.readu8(mask, segment.cell) == 1 then\n\t\t\t\t\ttable.insert(recolored, { segment = segment, previous = segment.colorInt })\n\t\t\t\t\tsegment.colorInt = colorInt\n\t\t\t\t\tsegment.frame.BackgroundColor3 = color\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend\n\n-- Rebuilds the grid from the remaining history (after an undo).\nfunction CanvasRenderer._rebuildGrid(self: Renderer)\n\tresetGrid(self.grid)\n\tfor _, item in self.items do\n\t\tif item.kind == \"stroke\" then\n\t\t\tlocal points = item.points :: { number }\n\t\t\tlocal thickness = item.thickness :: number\n\t\t\tfor i = 1, #points - 1, 2 do\n\t\t\t\tlocal px, py = points[i - 2], points[i - 1]\n\t\t\t\tif px then\n\t\t\t\t\tstamp(self.grid, px, py, points[i], points[i + 1], thickness, item.colorInt)\n\t\t\t\telse\n\t\t\t\t\tstamp(self.grid, points[i], points[i + 1], points[i], points[i + 1], thickness, item.colorInt)\n\t\t\t\tend\n\t\t\tend\n\t\telse\n\t\t\tflood(self.grid, item.x :: number, item.y :: number, item.colorInt)\n\t\tend\n\tend\nend\n\n-- Undo: removes a stroke or fill (normally the last one).\nfunction CanvasRenderer.remove(self: Renderer, id: number)\n\tlocal item = self.byId[id]\n\tif not item then\n\t\treturn\n\tend\n\tself.byId[id] = nil\n\tlocal index = table.find(self.items, item)\n\tif index then\n\t\ttable.remove(self.items, index)\n\tend\n\tif item.container then\n\t\titem.container:Destroy()\n\tend\n\tif item.recolored then\n\t\tfor i = #item.recolored, 1, -1 do\n\t\t\tlocal change = item.recolored[i]\n\t\t\tchange.segment.colorInt = change.previous\n\t\t\tchange.segment.frame.BackgroundColor3 = CanvasRenderer.toColor(change.previous)\n\t\tend\n\tend\n\tself:_rebuildGrid()\nend\n\nfunction CanvasRenderer.clear(self: Renderer)\n\tfor _, item in self.items do\n\t\tif item.container then\n\t\t\titem.container:Destroy()\n\t\tend\n\tend\n\ttable.clear(self.items)\n\ttable.clear(self.byId)\n\tself.layer = 0\n\tself.fillLayerZ = 0\n\tresetGrid(self.grid)\nend\n\nreturn CanvasRenderer\n"); put(client,"Theme","ModuleScript","-- Colours and fonts, modelled on skribbl.io: flat white panels, Nunito text,\n-- a monospace word, and green/blue/orange chat lines.\n\nlocal function fontFace(enum: Enum.Font, weight: Enum.FontWeight?): Font\n\treturn Font.new(Font.fromEnum(enum).Family, weight or Enum.FontWeight.Regular)\nend\n\nlocal Theme = {\n\tbackground = Color3.fromRGB(59, 106, 72),\n\n\tpanel = Color3.fromRGB(255, 255, 255),\n\trowAlt = Color3.fromRGB(236, 236, 236),\n\tborder = Color3.fromRGB(204, 204, 204),\n\ttext = Color3.fromRGB(20, 20, 20),\n\tmuted = Color3.fromRGB(110, 110, 110),\n\twhite = Color3.fromRGB(255, 255, 255),\n\toutline = Color3.fromRGB(15, 20, 30),\n\n\tyou = Color3.fromRGB(74, 157, 230), -- your own name in the player list\n\tguessedRow = Color3.fromRGB(150, 226, 128),\n\tdrawerRow = Color3.fromRGB(255, 236, 160),\n\tselected = Color3.fromRGB(170, 120, 230), -- the active tool / brush size\n\n\t-- The screen over the canvas between turns: a deep green to match the background.\n\toverlay = Color3.fromRGB(35, 82, 52),\n\toverlayTransparency = 0.04,\n\toverlayText = Color3.fromRGB(214, 240, 222),\n\n\t-- Chat colours\n\tgreen = Color3.fromRGB(86, 206, 39),\n\tgreenBg = Color3.fromRGB(231, 255, 223),\n\tblue = Color3.fromRGB(57, 117, 206),\n\torange = Color3.fromRGB(206, 79, 10),\n\tyellow = Color3.fromRGB(255, 211, 61),\n\tcloseText = Color3.fromRGB(200, 160, 0),\n\tcloseBg = Color3.fromRGB(255, 249, 214),\n\tred = Color3.fromRGB(230, 60, 60),\n\n\tgold = Color3.fromRGB(255, 205, 50),\n\tcrownText = Color3.fromRGB(196, 140, 0), -- the win count beside the crown\n\tsilver = Color3.fromRGB(200, 210, 222),\n\tbronze = Color3.fromRGB(222, 150, 92),\n\n\tregular = fontFace(Enum.Font.Nunito),\n\tbold = fontFace(Enum.Font.Nunito, Enum.FontWeight.Bold),\n\theavy = fontFace(Enum.Font.Nunito, Enum.FontWeight.ExtraBold),\n\tmono = fontFace(Enum.Font.RobotoMono),\n\tmonoBold = fontFace(Enum.Font.RobotoMono, Enum.FontWeight.Bold),\n\tlogo = fontFace(Enum.Font.FredokaOne),\n}\n\n-- Logo letters cycle through these, like skribbl.io's.\nTheme.rainbow = {\n\tColor3.fromRGB(239, 19, 11),\n\tColor3.fromRGB(255, 113, 0),\n\tColor3.fromRGB(255, 228, 0),\n\tColor3.fromRGB(0, 204, 0),\n\tColor3.fromRGB(0, 178, 255),\n\tColor3.fromRGB(35, 31, 211),\n\tColor3.fromRGB(163, 0, 186),\n\tColor3.fromRGB(223, 105, 167),\n}\n\nreturn Theme\n"); put(client,"Sounds","ModuleScript","-- Plays the UI sound effects listed in Config.SOUNDS. Sounds without an ID are skipped.\n\nlocal ContentProvider = game:GetService(\"ContentProvider\")\nlocal Debris = game:GetService(\"Debris\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal SoundService = game:GetService(\"SoundService\")\n\nlocal Config = require(ReplicatedStorage:WaitForChild(\"GuessAndDraw\"):WaitForChild(\"Config\"))\n\nlocal Sounds = {}\n\nSounds.muted = false\n\nlocal folder = Instance.new(\"Folder\")\nfolder.Name = \"GuessAndDrawSounds\"\nfolder.Parent = SoundService\n\nlocal templates: { [string]: Sound } = {}\nfor name, id in Config.SOUNDS do\n\tif typeof(id) == \"string\" and id ~= \"\" then\n\t\tlocal sound = Instance.new(\"Sound\")\n\t\tsound.Name = name\n\t\tsound.SoundId = id\n\t\tsound.Parent = folder\n\t\ttemplates[name] = sound\n\tend\nend\n\ntask.spawn(function()\n\tpcall(function()\n\t\tContentProvider:PreloadAsync(folder:GetChildren())\n\tend)\nend)\n\n-- `volume` scales Config.SOUND_VOLUME, so 0.5 plays at half the normal loudness.\nfunction Sounds.play(name: string, volume: number?)\n\tlocal template = templates[name]\n\tif not template or Sounds.muted then\n\t\treturn\n\tend\n\t-- A fresh copy per play lets the same sound overlap itself (fast ticks, many guesses).\n\tlocal sound = template:Clone()\n\tsound.Volume = Config.SOUND_VOLUME * (volume or 1)\n\tsound.Parent = folder\n\tsound:Play()\n\tDebris:AddItem(sound, 6)\nend\n\nreturn Sounds\n"); put(client,"Ui","ModuleScript","-- Building blocks for the UI (flat skribbl.io-style panels, text, buttons, avatars)\n-- and the small tween animations used everywhere.\n\nlocal GuiService = game:GetService(\"GuiService\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\n\nlocal Theme = require(script.Parent:WaitForChild(\"Theme\"))\nlocal Sounds = require(script.Parent:WaitForChild(\"Sounds\"))\n\nlocal Ui = {}\n\nfunction Ui.make(className: string, props: { [string]: any }, children: { Instance }?): any\n\tlocal instance = Instance.new(className)\n\tfor key, value in props do\n\t\tif key ~= \"Parent\" then\n\t\t\t(instance :: any)[key] = value\n\t\tend\n\tend\n\tfor _, child in children or {} do\n\t\tchild.Parent = instance\n\tend\n\t-- Roblox gives new GUI objects a 1px dark border; this look never wants it.\n\tif props.BorderSizePixel == nil and instance:IsA(\"GuiObject\") then\n\t\t(instance :: GuiObject).BorderSizePixel = 0\n\tend\n\tif props.Parent then\n\t\tinstance.Parent = props.Parent\n\tend\n\treturn instance\nend\n\nlocal make = Ui.make\n\nlocal function merge(defaults: { [string]: any }, props: { [string]: any })\n\tfor key, value in props do\n\t\tdefaults[key] = value\n\tend\n\treturn defaults\nend\n\nfunction Ui.corner(radius: number?): UICorner\n\treturn make(\"UICorner\", { CornerRadius = UDim.new(0, radius or 4) })\nend\n\n-- Fully rounded ends: circles and pills.\nfunction Ui.round(): UICorner\n\treturn make(\"UICorner\", { CornerRadius = UDim.new(0.5, 0) })\nend\n\nfunction Ui.pad(pixels: number, vertical: number?): UIPadding\n\tlocal h, v = UDim.new(0, pixels), UDim.new(0, vertical or pixels)\n\treturn make(\"UIPadding\", { PaddingLeft = h, PaddingRight = h, PaddingTop = v, PaddingBottom = v })\nend\n\nfunction Ui.maxText(size: number): UITextSizeConstraint\n\treturn make(\"UITextSizeConstraint\", { MaxTextSize = size })\nend\n\nfunction Ui.square(): UIAspectRatioConstraint\n\treturn make(\"UIAspectRatioConstraint\", { AspectRatio = 1 })\nend\n\n-- Outline around a frame or button.\nfunction Ui.border(thickness: number?, color: Color3?, transparency: number?): UIStroke\n\treturn make(\"UIStroke\", {\n\t\tApplyStrokeMode = Enum.ApplyStrokeMode.Border,\n\t\tThickness = thickness or 2,\n\t\tColor = color or Theme.border,\n\t\tTransparency = transparency or 0,\n\t})\nend\n\n-- Outline around the letters of a text label.\nfunction Ui.textOutline(thickness: number?, color: Color3?): UIStroke\n\treturn make(\"UIStroke\", {\n\t\tApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,\n\t\tThickness = thickness or 2,\n\t\tColor = color or Theme.outline,\n\t\tLineJoinMode = Enum.LineJoinMode.Round,\n\t})\nend\n\nfunction Ui.label(props: { [string]: any }, children: { Instance }?): TextLabel\n\treturn make(\n\t\t\"TextLabel\",\n\t\tmerge({ BackgroundTransparency = 1, TextColor3 = Theme.text, FontFace = Theme.bold, TextScaled = true }, props),\n\t\tchildren\n\t)\nend\n\n-- Big white heading text, as on the dark canvas overlay.\nfunction Ui.title(props: { [string]: any }, children: { Instance }?): TextLabel\n\treturn Ui.label(merge({ FontFace = Theme.heavy, TextColor3 = Theme.white }, props), children)\nend\n\n-- A flat white panel with slightly rounded corners.\nfunction Ui.panel(props: { [string]: any }, children: { Instance }?): Frame\n\tlocal list = children or {}\n\ttable.insert(list, Ui.corner(4))\n\treturn make(\"Frame\", merge({ BackgroundColor3 = Theme.panel, BorderSizePixel = 0 }, props), list)\nend\n\n-- Pointer position in the same space as AbsolutePosition. Roblox measures GUI\n-- positions and InputObject.Position from just below the topbar (even in a ScreenGui\n-- that ignores the inset), while GetMouseLocation() counts from the very top of the\n-- window, so the topbar height has to come off that one.\nfunction Ui.pointerPosition(input: InputObject?): Vector2\n\tif input then\n\t\treturn Vector2.new(input.Position.X, input.Position.Y)\n\tend\n\treturn UserInputService:GetMouseLocation() - GuiService:GetGuiInset()\nend\n\nfunction Ui.isPress(input: InputObject): boolean\n\treturn input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch\nend\n\nfunction Ui.contains(gui: GuiObject, point: Vector2): boolean\n\tlocal relative = point - gui.AbsolutePosition\n\treturn relative.X >= 0 and relative.Y >= 0 and relative.X <= gui.AbsoluteSize.X and relative.Y <= gui.AbsoluteSize.Y\nend\n\n-- Animation --------------------------------------------------------------------------\n\nfunction Ui.tween(\n\tinstance: Instance,\n\tseconds: number,\n\tgoal: { [string]: any },\n\tstyle: Enum.EasingStyle?,\n\tdirection: Enum.EasingDirection?\n): Tween\n\tlocal tween = TweenService:Create(\n\t\tinstance,\n\t\tTweenInfo.new(seconds, style or Enum.EasingStyle.Quad, direction or Enum.EasingDirection.Out),\n\t\tgoal\n\t)\n\ttween:Play()\n\treturn tween\nend\n\nfunction Ui.scaleOf(gui: GuiObject): UIScale\n\tlocal scale = gui:FindFirstChildOfClass(\"UIScale\")\n\tif not scale then\n\t\tscale = make(\"UIScale\", { Parent = gui })\n\tend\n\treturn scale :: UIScale\nend\n\n-- Springs the element in from small (or large) to full size.\nfunction Ui.pop(gui: GuiObject, from: number?, seconds: number?)\n\tlocal scale = Ui.scaleOf(gui)\n\tscale.Scale = from or 0.5\n\tUi.tween(scale, seconds or 0.4, { Scale = 1 }, Enum.EasingStyle.Back)\nend\n\n-- A quick bump in size and back.\nfunction Ui.pulse(gui: GuiObject, amount: number?)\n\tlocal scale = Ui.scaleOf(gui)\n\tscale.Scale = amount or 1.2\n\tUi.tween(scale, 0.35, { Scale = 1 }, Enum.EasingStyle.Back)\nend\n\nfunction Ui.shake(gui: GuiObject, degrees: number?)\n\tlocal angle = degrees or 8\n\ttask.spawn(function()\n\t\tfor _, rotation in { angle, -angle, angle * 0.6, -angle * 0.6, 0 } do\n\t\t\tUi.tween(gui, 0.05, { Rotation = rotation }, Enum.EasingStyle.Sine).Completed:Wait()\n\t\tend\n\tend)\nend\n\n-- Loops forever between the current and the given property values.\nfunction Ui.loop(instance: Instance, seconds: number, goal: { [string]: any })\n\tTweenService:Create(\n\t\tinstance,\n\t\tTweenInfo.new(seconds, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),\n\t\tgoal\n\t):Play()\nend\n\n-- Grows a little on hover and shrinks while pressed.\nfunction Ui.hoverable(target: GuiButton, scaleTarget: GuiObject?)\n\tlocal scale = Ui.scaleOf(scaleTarget or target)\n\tlocal hovering = false\n\ttarget.MouseEnter:Connect(function()\n\t\thovering = true\n\t\tUi.tween(scale, 0.12, { Scale = 1.06 })\n\tend)\n\ttarget.MouseLeave:Connect(function()\n\t\thovering = false\n\t\tUi.tween(scale, 0.12, { Scale = 1 })\n\tend)\n\ttarget.MouseButton1Down:Connect(function()\n\t\tUi.tween(scale, 0.08, { Scale = 0.92 })\n\tend)\n\ttarget.MouseButton1Up:Connect(function()\n\t\tUi.tween(scale, 0.2, { Scale = if hovering then 1.06 else 1 }, Enum.EasingStyle.Back)\n\tend)\nend\n\n-- Buttons ------------------------------------------------------------------------------\n\n-- The outlined white button used on the dark canvas overlay (word choices). It\n-- fills white on hover. Takes Text plus any layout props.\nfunction Ui.overlayButton(props: { [string]: any }): TextButton\n\tlocal text = props.Text or \"\"\n\tprops.Text = \"\"\n\tlocal button = make(\n\t\t\"TextButton\",\n\t\tmerge({ BackgroundColor3 = Theme.white, BackgroundTransparency = 1, AutoButtonColor = false }, props),\n\t\t{ Ui.corner(8), Ui.border(3, Theme.white) }\n\t)\n\tlocal caption = Ui.title({ Size = UDim2.fromScale(1, 1), Text = text, Parent = button }, { Ui.maxText(30), Ui.pad(10, 6) })\n\tUi.hoverable(button)\n\tbutton.MouseEnter:Connect(function()\n\t\tUi.tween(button, 0.12, { BackgroundTransparency = 0 })\n\t\tUi.tween(caption, 0.12, { TextColor3 = Theme.overlay })\n\tend)\n\tbutton.MouseLeave:Connect(function()\n\t\tUi.tween(button, 0.12, { BackgroundTransparency = 1 })\n\t\tUi.tween(caption, 0.12, { TextColor3 = Theme.white })\n\tend)\n\tbutton.Activated:Connect(function()\n\t\tSounds.play(\"click\")\n\tend)\n\treturn button\nend\n\n-- A white square tool button (toolbar), holding an icon or a custom child.\nfunction Ui.toolButton(props: { [string]: any }): TextButton\n\tlocal button = make(\n\t\t\"TextButton\",\n\t\tmerge({ Text = \"\", BackgroundColor3 = Theme.white, AutoButtonColor = false, Size = UDim2.fromScale(1, 1) }, props),\n\t\t{ Ui.corner(6), Ui.square() }\n\t)\n\tUi.hoverable(button)\n\tbutton.Activated:Connect(function()\n\t\tSounds.play(\"click\", 0.5)\n\tend)\n\treturn button\nend\n\n-- Pencil -------------------------------------------------------------------------------\n\n-- skribbl.io's chunky pencil: pink eraser, striped orange body and a sharpened tip,\n-- leaning to the right. `props` places and sizes it (it keeps a 1:3.4 shape);\n-- OutlineThickness sets the black outline.\nfunction Ui.pencil(props: { [string]: any }): Frame\n\tlocal outline = props.OutlineThickness or 2\n\tprops.OutlineThickness = nil\n\tlocal ink = Color3.fromRGB(10, 10, 10)\n\tlocal pencil = make(\"Frame\", merge({ BackgroundTransparency = 1, Rotation = 25 }, props), {\n\t\tmake(\"UIAspectRatioConstraint\", { AspectRatio = 1 / 3.4 }),\n\t})\n\t-- The tip is a diamond centred on the bottom of the body; the body hides its top\n\t-- half, leaving a point. A smaller dark diamond makes the lead.\n\tmake(\"Frame\", {\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.fromScale(0.5, 0.794),\n\t\tSize = UDim2.fromScale(0.72, 1),\n\t\tRotation = 45,\n\t\tBackgroundColor3 = Color3.fromRGB(245, 205, 155),\n\t\tZIndex = 1,\n\t\tParent = pencil,\n\t}, { Ui.square(), Ui.border(outline, ink) })\n\tmake(\"Frame\", {\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.fromScale(0.5, 0.898),\n\t\tSize = UDim2.fromScale(0.22, 1),\n\t\tRotation = 45,\n\t\tBackgroundColor3 = Color3.fromRGB(40, 40, 40),\n\t\tZIndex = 2,\n\t\tParent = pencil,\n\t}, { Ui.square() })\n\tmake(\"Frame\", {\n\t\tPosition = UDim2.fromScale(0, 0.147),\n\t\tSize = UDim2.fromScale(1, 0.647),\n\t\tBackgroundColor3 = Color3.fromRGB(245, 140, 40),\n\t\tZIndex = 3,\n\t\tParent = pencil,\n\t}, {\n\t\tUi.border(outline, ink),\n\t\tmake(\"Frame\", {\n\t\t\tPosition = UDim2.fromScale(0.26, 0.04),\n\t\t\tSize = UDim2.fromScale(0.13, 0.92),\n\t\t\tBackgroundColor3 = Color3.fromRGB(255, 192, 110),\n\t\t\tBorderSizePixel = 0,\n\t\t}),\n\t\tmake(\"Frame\", {\n\t\t\tPosition = UDim2.fromScale(0.6, 0.04),\n\t\t\tSize = UDim2.fromScale(0.13, 0.92),\n\t\t\tBackgroundColor3 = Color3.fromRGB(255, 192, 110),\n\t\t\tBorderSizePixel = 0,\n\t\t}),\n\t})\n\tmake(\"Frame\", { -- eraser\n\t\tSize = UDim2.fromScale(1, 0.17),\n\t\tBackgroundColor3 = Color3.fromRGB(250, 150, 205),\n\t\tZIndex = 4,\n\t\tParent = pencil,\n\t}, { Ui.corner(5), Ui.border(outline, ink) })\n\treturn pencil\nend\n\n-- Avatars ------------------------------------------------------------------------------\n\n-- The player's avatar headshot. Shows their initial in a circle when there is no\n-- picture (Studio test players have no avatar).\nfunction Ui.avatar(userId: number?, name: string?, props: { [string]: any }): Frame\n\tlocal frame = make(\"Frame\", merge({ BackgroundTransparency = 1 }, props))\n\tif userId and userId > 0 then\n\t\tmake(\"ImageLabel\", {\n\t\t\tSize = UDim2.fromScale(1, 1),\n\t\t\tBackgroundTransparency = 1,\n\t\t\tImage = `rbxthumb://type=AvatarHeadShot&id={userId}&w=150&h=150`,\n\t\t\tParent = frame,\n\t\t})\n\telse\n\t\tmake(\"Frame\", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Theme.border, Parent = frame }, {\n\t\t\tUi.round(),\n\t\t\tUi.label({\n\t\t\t\tSize = UDim2.fromScale(1, 1),\n\t\t\t\tText = string.upper(string.sub(name or \"?\", 1, 1)),\n\t\t\t\tTextColor3 = Theme.white,\n\t\t\t\tFontFace = Theme.heavy,\n\t\t\t}, { Ui.pad(6) }),\n\t\t})\n\tend\n\treturn frame\nend\n\nreturn Ui\n"); put(client,"Effects","ModuleScript","-- Full-screen effects drawn on their own layer: confetti and floating \"+points\" text.\n\nlocal Debris = game:GetService(\"Debris\")\n\nlocal Theme = require(script.Parent:WaitForChild(\"Theme\"))\nlocal Ui = require(script.Parent:WaitForChild(\"Ui\"))\n\nlocal Effects = {}\n\nlocal layer: Frame? = nil\n\n-- `effectsLayer` must cover the whole screen and sit above everything else.\nfunction Effects.init(effectsLayer: Frame)\n\tlayer = effectsLayer\nend\n\nfunction Effects.confetti(count: number?)\n\tif not layer then\n\t\treturn\n\tend\n\tfor _ = 1, count or 90 do\n\t\tlocal width = math.random(8, 15)\n\t\tlocal startX = math.random()\n\t\tlocal piece = Ui.make(\"Frame\", {\n\t\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\t\tPosition = UDim2.fromScale(startX, -0.05 - math.random() * 0.35),\n\t\t\tSize = UDim2.fromOffset(width, math.floor(width * 0.6)),\n\t\t\tRotation = math.random(0, 360),\n\t\t\tBackgroundColor3 = Theme.rainbow[math.random(#Theme.rainbow)],\n\t\t\tBorderSizePixel = 0,\n\t\t\tParent = layer,\n\t\t}, { Ui.corner(2) })\n\t\tlocal seconds = 2.4 + math.random() * 1.8\n\t\tUi.tween(piece, seconds, {\n\t\t\tPosition = UDim2.fromScale(startX + (math.random() - 0.5) * 0.3, 1.1),\n\t\t\tRotation = piece.Rotation + math.random(-720, 720),\n\t\t}, Enum.EasingStyle.Sine, Enum.EasingDirection.In)\n\t\tDebris:AddItem(piece, seconds + 0.1)\n\tend\nend\n\n-- Pops up text at a screen position (in AbsolutePosition terms), then drifts it\n-- upward and fades it out.\nfunction Effects.floatText(text: string, color: Color3, position: Vector2, textSize: number?)\n\tif not layer then\n\t\treturn\n\tend\n\t-- The layer's own corner isn't at 0, 0 (it starts above the topbar), so place\n\t-- the text relative to it.\n\tposition -= layer.AbsolutePosition\n\tlocal outline = Ui.textOutline(3)\n\tlocal label = Ui.label({\n\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\tPosition = UDim2.fromOffset(position.X, position.Y),\n\t\tSize = UDim2.fromOffset(400, (textSize or 30) + 10),\n\t\tText = text,\n\t\tTextScaled = false,\n\t\tTextSize = textSize or 30,\n\t\tTextColor3 = color,\n\t\tFontFace = Theme.heavy,\n\t\tParent = layer,\n\t}, { outline })\n\tUi.pop(label, 0.3, 0.35)\n\ttask.delay(0.45, function()\n\t\tUi.tween(label, 0.9, { Position = UDim2.fromOffset(position.X, position.Y - 60), TextTransparency = 1 })\n\t\tUi.tween(outline, 0.9, { Transparency = 1 })\n\tend)\n\tDebris:AddItem(label, 1.5)\nend\n\n-- Centre of a GUI object on screen, handy as a floatText position.\nfunction Effects.centreOf(gui: GuiObject): Vector2\n\treturn gui.AbsolutePosition + gui.AbsoluteSize / 2\nend\n\nreturn Effects\n"); put(client,"ColorPicker","ModuleScript","-- A colour wheel popup: drag on the wheel to pick the hue (around) and how vivid\n-- it is (out from the white centre), and on the slider below for brightness. It's\n-- built from Frames and gradients, so it needs no uploaded image.\n\nlocal UserInputService = game:GetService(\"UserInputService\")\n\nlocal Theme = require(script.Parent:WaitForChild(\"Theme\"))\nlocal Ui = require(script.Parent:WaitForChild(\"Ui\"))\n\nlocal make = Ui.make\n\nlocal SPOKES = 144 -- thin wedges of colour that make up the wheel\nlocal TAU = 2 * math.pi\n\nlocal ColorPicker = {}\nColorPicker.__index = ColorPicker\n\nexport type Picker = typeof(setmetatable(\n\t{} :: {\n\t\tpanel: Frame,\n\t\thue: number,\n\t\tsaturation: number,\n\t\tvalue: number,\n\t\tonPick: (Color3) -> (),\n\t\t_refresh: () -> (),\n\t},\n\tColorPicker\n))\n\n-- `props` positions the popup (Position, Size, Parent). `onPick` is called with\n-- every colour picked, while dragging too.\nfunction ColorPicker.new(props: { [string]: any }, onPick: (Color3) -> ()): Picker\n\tlocal panel = Ui.panel({\n\t\tPosition = props.Position,\n\t\tSize = props.Size,\n\t\tVisible = false,\n\t\tZIndex = 20,\n\t\tParent = props.Parent,\n\t}, { Ui.border(2, Theme.border) })\n\n\t-- The wheel: spokes running from white at the centre to the full hue at the rim.\n\tlocal wheel = make(\"Frame\", {\n\t\tAnchorPoint = Vector2.new(0.5, 0),\n\t\tPosition = UDim2.fromScale(0.5, 0.04),\n\t\tSize = UDim2.fromScale(0.86, 0.66),\n\t\tBackgroundColor3 = Theme.white,\n\t\tParent = panel,\n\t}, { Ui.square(), Ui.round() })\n\tfor i = 0, SPOKES - 1 do\n\t\tlocal angle = i / SPOKES * TAU\n\t\t-- GUI objects rotate about their centre, so each spoke is centred halfway out.\n\t\tmake(\"Frame\", {\n\t\t\tAnchorPoint = Vector2.new(0.5, 0.5),\n\t\t\tPosition = UDim2.fromScale(0.5 + 0.25 * math.cos(angle), 0.5 +